templates.template:
/* AVATAR EDITOR */

.xenOverlay.avatarEditor
{
	max-width: 720px;
}

.AvatarEditor
{
	overflow: hidden; zoom: 1;
	margin: 0 auto;
}

/* current avatar large display */

.AvatarEditor .currentAvatar
{
	float: left;
	display: block;
	width: 192px;
	text-align: center;
}

	.AvatarEditor .currentAvatar img
	{
		max-width: 192px;
	}

/* controls column */

.AvatarEditor .modifyControls
{
	margin-left: 210px;
}

	.AvatarEditor .avatarUpload
	{
		max-width: 100%;
		box-sizing: border-box;
	}

	.AvatarEditor .avatarOption
	{
		overflow: hidden; zoom: 1;
		padding: 10px;
		margin-bottom: 10px;
	}

	.AvatarEditor label
	{
		display: block;
	}

	.AvatarEditor .avatarLabel
	{
		display: block;
		float: left;
	}

		.AvatarEditor .avatarCropper img
		{
			cursor: move;
		}

	.AvatarEditor .radioOption
	{
		float: left;
		margin-left: 10px;
		margin-top: 2px;
	}

	.AvatarEditor .labelText
	{
		margin-left: 130px;
	}

		.AvatarEditor .explain
		{
			display: block;
			font-size: 11px;
			margin-bottom: 10px;
		}

			.AvatarEditor .saveHint
			{
				font-style: italic;
			}

		.AvatarEditor #GravatarEmail
		{
			width: 175px;
		}

		.AvatarEditor #GravatarTest
		{
			width: 50px;
		}

		.AvatarEditor #GravatarError
		{
			color: red;
			display: block;
		}

/* bottom controls row */

.AvatarEditor .submitUnit
{
	overflow: hidden; zoom: 1;
	padding-bottom: 10px;
}

	.AvatarEditor .submitUnit label.deleteCtrl
	{
		float: left;
	}

	.AvatarEditor .submitUnit .buttons
	{
		float: right;
	}

		.AvatarEditor .submitUnit .buttons .button
		{
			min-width: 70px;
		}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:700px)
{
	.Responsive .AvatarEditor .currentAvatar
	{
		display: none;
	}

	.Responsive .AvatarEditor .modifyControls
	{
		margin-left: 0;
	}
}

@media (max-width:{xen:property maxResponsiveNarrowWidth})
{
	.Responsive .AvatarEditor .avatarLabel
	{
		float: none;
		margin: 0 auto;
		text-align: center;
	}

	.Responsive .AvatarEditor .labelText
	{
		margin-left: 0;
	}

	.Responsive .AvatarEditor .radioOption
	{
		margin: 0;
	}
}
</xen:if>

.upgrade
{
	overflow: hidden; zoom: 1;
}

	.sectionMain.mainContentBlock .upgrade.primaryContent
	{
		margin: 0;
		padding: 5px;
		box-shadow: none;
		background: transparent none;
		border-width: 0;
		border-radius: 0;
		border-top: 1px solid {xen:property innerTopBorder};
		border-bottom: 1px solid {xen:property innerBottomBorder};
	}

		.sectionMain.mainContentBlock .upgrade.primaryContent:first-child
		{
			border-top-width: 0;
		}

		.sectionMain.mainContentBlock .upgrade.primaryContent:last-child
		{
			border-bottom-width: 0;
		}

.upgradeMain
{
	margin-right: 160px;
}
	.upgradeMain .title
	{
		font-size: 11pt;
	}

	.upgradeMain .description
	{
		font-size: 11px;
	}

.upgradeForm
{
	float: right;
	width: 150px;
	font-size: 11px;
}

	.upgradeForm .button
	{
		margin-top: 5px;
	}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveMediumWidth})
{
	.Responsive .upgrade
	{
		display: table;
		width: 100%;
		box-sizing: border-box;
	}

	.Responsive .upgradeForm
	{
		display: table-footer-group;
		float: none;
		width: auto;
	}

		.Responsive .upgradeForm .cost
		{
			float: left;
			margin-top: 5px;
		}

		.Responsive .upgradeForm .button
		{
			margin-top: 0;
			float: right;
		}

	.Responsive .upgradeMain
	{
		margin: 0;
		display: table-cell;
		padding-bottom: 5px;
	}
}
</xen:if>

/* XenTag */
.sectionMain.Tinhte_XenTag_Tags_ThreadView
{
	{xen:property primaryContent}
}

.Tinhte_XenTag_TagsEditor .Tinhte_XenTag_TagNew .textCtrl.Tinhte_XenTag_TagNewInput
{
	color: {xen:property contentText};
}

.Tinhte_XenTag_TagsEditor li.Tinhte_XenTag_Tag
{
	{xen:property button}
}

	.Tinhte_XenTag_TagsEditor li.Tinhte_XenTag_Tag a.delete
	{
		color: inherit;
	}

	.Tinhte_XenTag_TagsEditor li.Tinhte_XenTag_Tag:hover
	{
		{xen:property buttonHover}
	}

	.Tinhte_XenTag_TagsEditor li.Tinhte_XenTag_Tag:active
	{
		{xen:property buttonActive}
	}

/* the attached files block is intended to appear like a bb code block */

.attachedFiles
{
	{xen:property bbCodeBlock}
}

.messageList.withSidebar .attachedFiles
{
	margin-right: 0px;
}

	.attachedFiles .attachedFilesHeader
	{
		{xen:property bbCodeBlockType}

		padding: 4px 8px;
	}

	.attachedFiles .attachmentList
	{
		/* roughly the same as "bbCodeCode" with the monospacing stuff removed */
		overflow: hidden; zoom: 1;		
		{xen:property attachmentList}
	}

		.attachment
		{
			float: left;
			width: 50%;
			max-width: 300px;
		}

		.attachment .boxModelFixer
		{
			overflow: hidden; zoom: 1;
			{xen:property attachmentItem}
		}

			<xen:set var="$attachThumbSize">{xen:calc 'min(100, {$xenOptions.attachmentThumbnailDimensions} / 2)'}px</xen:set>

			.attachment .thumbnail
			{
				float: left;						
				width: {$attachThumbSize};
				height: {$attachThumbSize};
				overflow: hidden;
				{xen:property attachmentThumbnail}
			}

				.attachment .thumbnail .SquareThumb
				{
					width: {$attachThumbSize};
					height: {$attachThumbSize};
					{xen:property attachmentThumbnailSquare}
				}

				.attachment .thumbnail .genericAttachment
				{
					{xen:property genericAttachmentThumb}

					margin: {xen:calc '({$xenOptions.attachmentThumbnailDimensions} / 2 - {xen:property genericAttachmentThumb.height}) / 2'}px {xen:calc '({$xenOptions.attachmentThumbnailDimensions} / 2 - {xen:property genericAttachmentThumb.width}) / 2'}px !important;
				}

		.attachment .attachmentInfo
		{
			white-space: nowrap;
			overflow: hidden; zoom: 1;
			font-size: 11px;
			padding-left: 5px;
		}

			.attachment .attachmentInfo .filename
			{
				text-overflow: ellipsis;
				overflow: hidden;
				max-width: 100%;
			}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveWideWidth})
{
	.Responsive .attachedFiles
	{
		margin-right: 0;
	}
}

@media (max-width:{xen:property maxResponsiveMediumWidth})
{
	html.Responsive .attachment
	{
		width: 100%;
	}
}
</xen:if>

.AttachmentEditor
{
	clear: both;
}

.xenForm .ctrlUnit dd li.AttachedFile,
.xenForm .ctrlUnit dd .AttachmentInsertAllBlock
{
	margin-top: 0;
	margin-right: {xen:property ctrlUnitEdgeSpacer};
}

.AttachmentEditor .AttachedFile,
.AttachmentEditor .AttachmentInsertAllBlock
{
	overflow: hidden; zoom: 1;
	vertical-align: middle;
	padding: 5px 10px;
}

	.primaryContent .AttachmentEditor .AttachedFile,
	.primaryContent .AttachmentEditor .AttachmentInsertAllBlock
	{
		box-shadow: none;
		background-color: {xen:property blocksInnerBackground};
		background-image: none;
	}

.AttachmentEditor .AttachedFile#AttachedFileTemplate
{
	display: none;
}

	.AttachmentEditor .AttachedFile .Thumbnail
	{
		width: 54px;
		height: 54px;
		line-height: 50px;
		display: block;
		background: {xen:property content.background-color};
		border: 1px solid {xen:property blocksInnerBorder};
		text-align: center;
		vertical-align: middle;
		float: left;
	}

		.AttachmentEditor .AttachedFile .Thumbnail img
		{
			max-width: 50px;
			max-height: 50px;
			_width: 50px;
			_height: 50px;
			padding: 0;
			margin: 0;
			vertical-align: middle;
		}

		.AttachmentEditor .AttachedFile .Thumbnail .genericAttachment
		{			
			{xen:property genericAttachmentThumb}

			margin: {xen:calc '(50 - {xen:property genericAttachmentThumb.width}) / 2'}px;
		}

		<xen:if is="{xen:property nodeIconHD}">
		@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi), (min-resolution: 1.5dppx)
		{
			.AttachmentEditor .AttachedFile .Thumbnail .genericAttachment
			{
				{xen:property nodeIconPageHD}
			}
		}
		</xen:if>

	.AttachmentEditor .AttachmentText
	{
		margin-left: 64px;
	}

		.AttachmentEditor .AttachedFile .Filename
		{
		}

		.AttachmentEditor .secondaryContent .label
		{
			margin-bottom: 2px;
			font-size: 11px;
			color: {xen:property mutedTextColor};
		}

		.AttachmentEditor .secondaryContent .controls
		{
			line-height: 25px;
		}

		{xen:helper clearfix, '.AttachmentEditor .AttachedFile .controls'}


		.AttachmentEditor .AttachedFile .ProgressMeter
		{
			display: block;
			padding: 2px;
			border: 1px solid {xen:property primaryLighter};
			border-radius: 4px;
			background-color: {xen:property content.background-color};
			margin-right: 75px;
			margin-top: 4px;
			font-size: 14pt;
			line-height: 26px;
		}

			.AttachmentEditor .AttachedFile .ProgressMeter .ProgressGraphic
			{
				display: inline-block;
				width: 0%;
				height: 26px;
				background: {xen:property primaryLight} url('{xen:property imagePath}/xenforo/gradients/category-23px-light.png') repeat-x top;
				text-align: right;
			}

			.AttachmentEditor .AttachedFile .ProgressMeter .ProgressCounter
			{
				display: inline-block;
				height: 26px;
				padding: 0 10px;
			}

			.AttachmentEditor .AttachedFile .ProgressMeter .ProgressGraphic .ProgressCounter
			{
				color: {xen:property primaryLightest};
			}


			.AttachmentEditor .AttachedFile .AttachmentDeleter,
			.AttachmentEditor .AttachedFile .AttachmentCanceller
			{
				float: right;
				display: none;
			}

.AttachmentEditor .AttachmentInsertAllBlock
{
	display: none;
	margin-bottom: 5px;
}

	.AttachmentEditor .AttachmentInsertAllBlock span
	{
		float: left;
		display: block;
		width: 54px;
		height: 34px;
		background: {xen:property content.background-color} url('{xen:property imagePath}/xenforo/widgets/image-attachments.png') no-repeat center;
		margin-right: 10px;
	}

.AttachmentEditor .AttachmentDeleteAll
{
	float: right;
}

.AttachmentEditor .AttachmentList .secondaryContent
{
	margin-bottom: 5px;
}

/* SWFUploader placeholder */

.swfupload
{
	position: absolute;
	z-index: 1;
}

/* Uploader JS Overlay */

.xenOverlay.attachmentUploader
{
	max-width: 500px;
}

.attachmentUploader #ctrl_upload
{
