/* .bbCodeX classes are designed to exist inside .baseHtml. ie: they have no CSS reset applied */

.bbCodeBlock
{
	{xen:property bbCodeBlock}
}

	.bbCodeBlock .bbCodeBlock,
	.hasJs .bbCodeBlock .bbCodeSpoilerText,
	.messageList.withSidebar .bbCodeBlock
	{
		margin-right: 0;
	}

	/* mini CSS reset */
	.bbCodeBlock pre,
	.bbCodeBlock blockquote
	{
		margin: 0;
	}

	.bbCodeBlock img
	{
		border: none;
	}

.bbCodeBlock .type
{
	{xen:property bbCodeBlockType}
}

.bbCodeBlock pre,
.bbCodeBlock .code
{
	{xen:property bbCodeCode}
}

.bbCodeBlock .code
{
	white-space: nowrap;
}

.bbCodeQuote
{
	{xen:property bbCodeQuote}
}

.bbCodeQuote .attribution
{
	{xen:property bbCodeQuoteAttribution}
}

.bbCodeQuote .quoteContainer
{
	overflow: hidden;
	position: relative;

	{xen:property bbCodeQuoteMessage}
}

	.bbCodeQuote .bbCodeQuote,
	.bbCodeQuote .bbCodeBlock,
	.bbCode > dl > dd .bbCodeQuote,
	.bbCode > dl > dd .bbCodeBlock
	{
		{xen:property nestedBBCode}
	}

<xen:if is="{xen:property bbCodeQuoteMaxHeight}">
	.bbCodeQuote .quoteContainer .quote
	{
		max-height: {xen:property bbCodeQuoteMaxHeight};
		overflow: hidden;
		padding-bottom: 1px;
	}

		.NoJs .bbCodeQuote .quoteContainer .quote
		{
			max-height: none;
		}

	.bbCodeQuote .quoteContainer .quoteExpand
	{		
		display: none;
		box-sizing: border-box;
		position: absolute;
		height: 80px;
		top: {xen:calc '{xen:property bbCodeQuoteMaxHeight} + {xen:property bbCodeQuoteMessage.padding-top} + {xen:property bbCodeQuoteMessage.padding-bottom} - 80'}px;
		left: 0;
		right: 0;

		font-size: 11px;
		line-height: 1;
		text-align: center;
		color: {xen:property secondaryLight};
		cursor: pointer;
		padding-top: 65px;
		<xen:if is="{xen:property bbCodeQuoteMessage.background-color} != ''">
			<xen:set var="$bg">{xen:property bbCodeQuoteMessage.background-color}</xen:set>
		<xen:elseif is="{xen:property bbCodeQuote.background-color} != ''" />
			<xen:set var="$bg">{xen:property bbCodeQuote.background-color}</xen:set>
		<xen:elseif is="{xen:property bbCodeBlock.background-color} != ''" />
			<xen:set var="$bg">{xen:property bbCodeBlock.background-color}</xen:set>
		<xen:else />
			<xen:set var="$bg">{xen:property blocksInnerBackground}</xen:set>
		</xen:if>
		<xen:set var="$bg0">{xen:helper rgba, {$bg}, 0}</xen:set>
		<xen:set var="$bg80">{xen:helper unrgba, {$bg}}</xen:set>
		background: -webkit-linear-gradient(top, {$bg0} 0%, {$bg80} 80%);
		background: -moz-linear-gradient(top, {$bg0} 0%, {$bg80} 80%);
		background: -o-linear-gradient(top, {$bg0} 0%, {$bg80} 80%);
		background: linear-gradient(to bottom, {$bg0} 0%, {$bg80} 80%);

		border-bottom-left-radius: {xen:property bbCodeQuoteMessage.border-bottom-left-radius};
		border-bottom-right-radius: {xen:property bbCodeQuoteMessage.border-bottom-right-radius};
	}

	.bbCodeQuote .quoteContainer .quoteExpand.quoteCut
	{
		display: block;
	}

	.bbCodeQuote .quoteContainer.expanded .quote
	{
		max-height: none;
	}

	.bbCodeQuote .quoteContainer.expanded .quoteExpand
	{
		display: none;
	}
<xen:else />
	.bbCodeQuote .quoteContainer .quoteExpand
	{
		display: none;
	}
</xen:if>

	.bbCodeQuote img
	{
		max-height: 150px;
	}

	.bbCodeQuote iframe,
	.bbCodeQuote object,
	.bbCodeQuote embed
	{
		max-width: 200px;
		max-height: 150px;
	}

	.bbCodeQuote iframe:-webkit-full-screen
	{
		max-width: none;
		max-height: none;
	}

	.bbCodeQuote iframe:-moz-full-screen
	{
		max-width: none;
		max-height: none;
	}

	.bbCodeQuote iframe:-ms-fullscreen
	{
		max-width: none;
		max-height: none;
	}

	.bbCodeQuote iframe:fullscreen
	{
		max-width: none;
		max-height: none;
	}

.bbCodeSpoilerButton
{
	margin: 5px 0;
	max-width: 99%;
}

	.bbCodeSpoilerButton > span
	{
		display: inline-block;
		max-width: 100%;
		white-space: nowrap;
		text-overflow: ellipsis;
		overflow: hidden;
	}

.hasJs .bbCodeSpoilerText
{
	display: none;
	{xen:property bbCodeSpoilerText}
}

	.hasJs .bbCodeSpoilerText .bbCodeSpoilerText,
	.hasJs .bbCodeSpoilerText .bbCodeBlock,
	.hasJs .messageList.withSidebar .bbCodeSpoilerText
	{
		margin-right: 0;
	}

.NoJs .bbCodeSpoilerContainer
{
	background-color: {xen:property contentText}; /* fallback for browsers without currentColor */
	background-color: currentColor;
}

	.NoJs .bbCodeSpoilerContainer > .bbCodeSpoilerText
	{
		visibility: hidden;
	}

	.NoJs .bbCodeSpoilerContainer:hover
	{
		background-color: transparent;
	}

		.NoJs .bbCodeSpoilerContainer:hover > .bbCodeSpoilerText
		{
			visibility: visible;
		}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveWideWidth})
{
	.Responsive .bbCodeBlock,
	.Responsive.hasJs .bbCodeSpoilerText
	{
		margin-right: 0;
	}
}
</xen:if>

.xenOverlay.chooserOverlay
{
	max-width: 700px;
}

	.chooserColumns
	{
		overflow: hidden; zoom: 1;
		padding: 0;
	}

		.chooserColumns li
		{
			float: left;
			width: 33%;
		}

			.chooserColumns.twoColumns li
			{
				width: 49.5%;
			}

			.chooserColumns.oneColumns li
			{
				width: 100%;
			}

			.chooserColumns.threeColumns li
			{
				width: 33%;
			}

			.chooserColumns.fourColumns li
			{
				width: 24.5%;
			}

			.chooserColumns li a
			{
				margin: 3px;
				display: block;
				padding: 5px 10px;
				border-radius: {xen:property secondaryContent.border-radius};
				overflow: hidden; zoom: 1;
			}

			.chooserColumns li a:hover
			{
				background-color: {xen:property blocksInnerBackground};
				text-decoration: none;
			}

			.chooserColumns .icon
			{
				float: left;
				display: block;
				width: 64px;
				height: 64px;
			}

				.styleChooser .icon
				{
					background-image: url('{xen:property imagePath}/xenforo/widgets/style-preview.png');
				}

			.chooserColumns .title,
			.chooserColumns .description
			{
				margin-left: 76px;
				display: block;
			}

			.chooserColumns .title
			{
				font-size: 11pt;
			}

				.chooserColumns .unselectable .title:after
				{
					content: " *";
				}

			.chooserColumns .description
			{
				color: {xen:property mutedTextColor};
				font-size: 11px;
			}

	.chooserScroller
	{
		overflow: auto;
		max-height: 200px;
	}

		.chooserScroller li a
		{
			display: block;
		}

		.chooserScroller li a:hover
		{
			text-decoration: none;
		}

			.chooserScroller li a .info
			{
				font-size: 11px;
				color: {xen:property contentText};	
			}

.chooserConfirm
{
	text-align: center;
}

	.chooserConfirm strong
	{
		display: block;
		margin-top: 10px;
		font-size: 18px;
	}

.chooserOverlaySearchWrapper
{
	overflow: hidden;
}

.chooserOverlaySearch
{
	float: right;
	padding-left: 18px;
	position: relative;
}

	.chooserOverlaySearch:after
	{
		position: absolute;
		left: 0;
		top: 50%;
		margin-top: -6px;
		content: '\f002';
		font-family: FontAwesome;
		font-size: 12px;
		line-height: 12px;
		color: {xen:property mutedTextColor};
	}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveNarrowWidth})
{
	.Responsive .chooserOverlay .chooserColumns li
	{
		width: auto;
		float: none;
	}

	.Responsive .chooserOverlaySearch
	{
		float: none;
		margin-top: 5px;
	}
}
</xen:if>

