#_atssh { display: none; }

/* Font Awesome entries */
.bx-wrapper .bx-prev:after,
.bx-wrapper .bx-next:after,
.bx-wrapper .bx-controls-auto .bx-start:after,
.bx-wrapper .bx-controls-auto .bx-stop:after
{
	position: absolute;
	left: 0;
	right: 0;
	top: 0;
	line-height: 1em;
	text-indent: 0;
	font-family: FontAwesome;
	font-weight: normal;
	font-style: normal;
	color: #fff;
	pointer-events: none;
	transition: opacity .2s ease;
	text-shadow: 1px 1px 2px rgba(0, 0, 0, .8);
}

/**
 * BxSlider v4.1.2 - Fully loaded, responsive content slider
 * http://bxslider.com
 *
 * Written by: Steven Wanderski, 2014
 * http://stevenwanderski.com
 * (while drinking Belgian ales and listening to jazz)
 *
 * CEO and founder of bxCreative, LTD
 * http://bxcreative.com
 */

.ctaFtSliderWrapper
{
	visibility: hidden;
	height: 0;
}	

.ctaFtSlider .bx-wrapper
{
	{xen:property ctaFtSlider}
}

.ctaFtSlider .bx-wrapper img
{
	{xen:property ctaFtSliderImage}
}

.ctaFtSlider .bx-wrapper .bx-loading
{
	min-height: 50px;
	background: url({xen:property imagePath}/images/cta-featured-threads-slider-loader.gif) center center no-repeat {xen:property textCtrlBackground};
	height: 100%;
	width: 100%;
	position: absolute;
	top: 0;
	left: 0;
	z-index: 2000;
}

.ctaFtSlider .bx-wrapper .bx-viewport
{
	{xen:property ctaFtSliderContainer}
}

.ctaFtSlider .bx-wrapper .bx-pager
{
	text-align: center;
	width: 100%;
	opacity: 0;
	-moz-transition: opacity .25s ease-in-out;
	-webkit-transition: opacity .25s ease-in-out;
	transition: opacity .25s ease-in-out;
}

.ctaFtSlider .bx-wrapper:hover .bx-pager,
.Touch .ctaFtSlider .bx-wrapper .bx-pager
{
	opacity: 1;
}

.ctaFtSlider .bx-wrapper .bx-controls-auto
{
	position: absolute;
	bottom: 57px;
}

.ctaFtSlider .bx-wrapper .bx-pager
{
	position: absolute;
	top: 10px;
}

.ctaFtSlider .bx-wrapper .bx-controls.bx-has-controls-auto.bx-has-pager .bx-pager
{
	text-align: center;
	width: 100%;
	opacity: 0;
	-moz-transition: opacity .25s ease-in-out;
	-webkit-transition: opacity .25s ease-in-out;
	transition: opacity .25s ease-in-out;
}

.ctaFtSlider .bx-wrapper:hover .bx-controls.bx-has-controls-auto.bx-has-pager .bx-pager,
.Touch .ctaFtSlider .bx-wrapper .bx-controls.bx-has-controls-auto.bx-has-pager .bx-pager
{
	opacity: 1;
}

.ctaFtSlider .bx-wrapper .bx-controls.bx-has-controls-auto.bx-has-pager .bx-controls-auto
{
	right: 3px;
	width: 35px;
	opacity: 0;
	-moz-transition: opacity .25s ease-in-out;
	-webkit-transition: opacity .25s ease-in-out;
	transition: opacity .25s ease-in-out;
}

.ctaFtSlider .bx-wrapper:hover .bx-controls.bx-has-controls-auto.bx-has-pager .bx-controls-auto,
.Touch .ctaFtSlider .bx-wrapper .bx-controls.bx-has-controls-auto.bx-has-pager .bx-controls-auto
{
	opacity: 1;
}

.ctaFtSlider .bx-wrapper .bx-pager .bx-pager-item,
.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-controls-auto-item
{
	display: inline-block;
	*zoom: 1;
	*display: inline;
}

.ctaFtSlider .bx-wrapper .bx-pager.bx-default-pager a
{
	background: {xen:property dimmedTextColor};
	text-indent: -9999px;
	display: block;
	width: 10px;
	height: 10px;
	margin: 0 5px;
	outline: 0;
	border-radius: 5px;
}

.ctaFtSlider .bx-wrapper .bx-pager.bx-default-pager a:hover,
.ctaFtSlider .bx-wrapper .bx-pager.bx-default-pager a.active
{
	background: #000;
}

.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-start
{
	display: block;
	text-indent: -9999px;
	width: 10px;
	height: 11px;
	outline: 0;
	margin: 0 3px;
}

	.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-start:after
	{
		content: '\f0da';
		font-size: 14px;
		top: -1px;
		opacity: .75;
	}

	.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-start:hover:after,
	.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-start.active:after
	{
		opacity: 1;
	}

.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-stop
{
	display: block;
	text-indent: -9999px;
	width: 9px;
	height: 11px;
	outline: 0;
	margin: 0 3px;
	position: relative;
}

	.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-stop:after
	{
		content: '\f04c';
		font-size: 10px;
		opacity: .75;
	}

	.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-stop:hover:after,
	.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-stop.active:after
	{
		opacity: 1;
	}

	.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-start.active:after,
	.ctaFtSlider .bx-wrapper .bx-controls-auto .bx-stop.active:after
	{
		color: {xen:property secondaryMedium};
	}

.ctaFtSlider .bx-wrapper .bx-controls-direction a
{
	position: absolute;
	top: 45%;
	margin-top: -16px;
	outline: 0;
	width: 32px;
	height: 32px;
	text-indent: -9999px;
	z-index: 50;
	opacity: 0;
	-moz-transition: opacity .25s ease-in-out;
	-webkit-transition: opacity .25s ease-in-out;
	transition: opacity .25s ease-in-out;
}

.ctaFtSlider .bx-wrapper:hover .bx-controls-direction a,
.Touch .ctaFtSlider .bx-wrapper .bx-controls-direction a
{
	opacity: 1;
}

.ctaFtSlider .bx-wrapper .bx-controls-direction a.disabled
{
	display: none;
}

.ctaFtSlider .bx-wrapper .bx-prev
{
	rtl-raw.left: 10px;
}

.ctaFtSlider .bx-wrapper .bx-next
{
	rtl-raw.right: 10px;
}

.ctaFtSlider .bx-wrapper .bx-prev:after,
.ctaFtSlider .bx-wrapper .bx-next:after
{
	height: 32px;
	font-size: 30px;
	content: '\f0a9';
	opacity: .75;
}

	.ctaFtSlider .bx-wrapper .bx-prev:after
	{
		content: '\f0a8';
	}

	.ctaFtSlider .bx-wrapper .bx-prev:hover:after,
	.ctaFtSlider .bx-wrapper .bx-next:hover:after
	{
		opacity: 1;
	}


.ctaFtSliderFooter
{
	{xen:property ctaFtSliderFooter}
}

.ctaFtSliderThreadTitle
{
	{xen:property ctaFtSliderThreadTitle}
}

.ctaFtSliderThreadSnippet
{
	{xen:property ctaFtSliderThreadSnippet}
}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveMediumWidth})
