.discussionList
{
	position: relative;
	zoom: 1;

	{xen:property discussionList}
}

/* wrapper */
.discussionListWrapper
{
	{xen:property discussionListWrapper}
}

	.discussionListWrapper + .discussionListWrapper
	{
		{xen:property discussionListWrapperSecond}
	}

/* empty forum */
.discussionListItems > li.primaryContent,
.discussionList > .sectionHeaders + div.primaryContent
{
	{xen:property emptyDiscussionListRow}
}

/** column style and width **/

.discussionListItem,
.discussionListItem .innerBlock
{
	display: table;
	table-layout: fixed;
	word-wrap: normal;
	width: 100%;
	box-sizing: border-box;
}

	.discussionListItem.withInnerBlock
	{
		display: block;
		width: auto;
		border-radius: 0;
		border-width: 0;
		box-shadow: none;
		background: transparent;
	}

	.discussionListItem .listBlock
	{
		display: table-cell;
		vertical-align: middle;
	}

		.discussionList .posterAvatar
		{
			width: {xen:property discussionListAvatarWidth};
		}

		.discussionList .main
		{
			width: auto;
		}

			.discussionList .sectionHeaders .main .postDate
			{
				text-align: right;
			}

		.discussionList .stats
		{
			width: {xen:property discussionListStatsWidth};
		}

			.discussionList .sectionHeaders .stats .minor
			{
				text-align: right;
			}

		.discussionList .lastPost
		{
			width: {xen:property discussionListLastPostWidth};
			text-align: right;
			overflow: hidden;
		}

		.discussionList .statsLastPost /* combined last two columns */
		{
			width: {xen:calc '{xen:property discussionListStatsWidth} + {xen:property discussionListLastPostWidth}'}px;
		}

/* column headers */

.discussionList .sectionHeaders{xen:if '!{xen:property separateThreads}', '.compact'}
{	
	{xen:property primaryContent.border}

	border-width: 0;
	overflow: hidden;
}

.discussionList .sectionHeaders
{	
	{xen:property subHeading}

	<xen:if is="{$pageIsRtl}">
	{xen:property subHeadingRTL}
	</xen:if>

	padding: 0;
	display: table;
	table-layout: fixed;
	word-wrap: normal;
	width: 100%;

	{xen:property discussionListHeaders}
}


	.discussionList .discussionListFilters + .sectionHeaders
	{
		{xen:property discussionListHeadersAfterFilters}
	}

	.discussionList .discussionListItems + .discussionListItems
	{
		margin-top: 0;
	}

	.discussionList .discussionListItems + .sectionHeaders,
	.discussionList .discussionListItems + .discussionListItems.split
	{
		margin-top: 10px;
	}

	.discussionList .sectionHeaders dt,
	.discussionList .sectionHeaders dd
	{
		display: table-cell;
		vertical-align: middle;

		{xen:property discussionListHeadersSection}
	}

	.discussionList .sectionHeaders dt span
	{
		display: none !important;
	}

	.discussionList .sectionHeaders a
	{
		{xen:property discussionListHeadersLink}
	}

	.discussionList .sectionHeaders a:hover
	{
		text-decoration: none;
	}

	.discussionList .sectionHeaders dd a[href]:hover
	{
		{xen:property subHeadingHover}

		{xen:property discussionListHeadersLinkHover}
	}

	.discussionList .sectionHeaders .main a,
	.discussionList .sectionHeaders .stats a
	{
		float: left;
		width: 50%;
		white-space: nowrap;
	}

		.discussionList .sectionHeaders a span
		{
			{xen:property subHeading.padding}
			display: block;
		}

/** IE <8 **/
.discussionList .sectionHeaders,
.discussionListItem, .discussionListItem.innerBlock { *display: block; _vertical-align: bottom; }
.discussionList .sectionHeaders dt,
.discussionList .sectionHeaders dd,
.discussionListItem .listBlock     { *display: block; *float: left; }
.discussionListItem .listBlock     { _height: 52px; *min-height: 52px; } /* todo: should be calculation */
.discussionList .posterAvatar      { *width: 6.98%; }
.discussionListItem .posterAvatar  { *font-size: 0; }	
.discussionList .main              { *width: 56.98%; }
.discussionList .stats             { *width: 15.97%; }	
.discussionList .lastPost          { *width: 19.97%; }
.discussionList .statsLastPost     { *width: 35.97%; }
.discussionList .sectionHeaders dt,
.discussionList .sectionHeaders dd { *padding: 5px 0; }
.discussionList .sectionHeaders a,
.discussionList .sectionHeaders a span { *display: inline !important; *float: none !important; }

/* items in thread list */

.discussionListItems
{
	<xen:if is="{xen:property separateThreads}">
	padding-bottom: {xen:property discussionListItemWrapperSeparate.padding-top};
	</xen:if>
}

	.discussionListItems:last-child
	{
		padding-bottom: 0;
	}




/* individual thread list item */

/** main **/

.discussionListItem,
.discussionListItem .innerBlock
{
	{xen:property primaryContent.background}

	{xen:property primaryContent.border}
}

	.discussionListItem.withInnerBlock
	{
		{xen:property discussionListItemWrapper}
		<xen:if is="{xen:property separateThreads}">
		{xen:property discussionListItemWrapperSeparate}
		</xen:if>
	}

		.compact .discussionListItem.withInnerBlock
		{
			{xen:property discussionListItemWrapperSeparate}
		}

		.discussionListItem .innerBlock
		{
			{xen:property discussionListItem}
		}

			.discussionListItem.sticky .innerBlock
			{
				{xen:property discussionListItemSticky}
			}

			.discussionListItem:first-child .innerBlock
			{
				{xen:property discussionListItemFirstRow}
			}

			.discussionListItem:last-child .innerBlock
			{
				{xen:property discussionListItemLastRow}
			}

	/* sections, section widths */
	.discussionListItem .listBlock
	{
		{xen:property discussionListItemSection}
	}

		.discussionListItem .posterAvatar,		
		.discussionListItem .lastPost
		{
			{xen:property primaryContent.border}
			border-width: 0;
		}

			.discussionListItem .posterAvatar
			{
				{xen:property discussionListItemAvatar}
			}

			.discussionListItem .main
			{
				{xen:property discussionListItemMain}
			}

			.discussionListItem .stats
			{
				{xen:property discussionListItemStats}
			}

			.discussionListItem .lastPost
			{
				{xen:property discussionListItemLastPost}
			}





	/* avatar section */

	.discussionListItem .posterAvatar .avatarContainer
	{
		display: block;
		position: relative;
	}

	.discussionListItem .posterAvatar .avatar
	{
		{xen:property discussionListAvatar}

		width: auto;
		height: auto;
	}

		.discussionListItem .posterAvatar .avatar img
		{
			width: {xen:property discussionListAvatar.width};
			height: {xen:property discussionListAvatar.height};
			display: block;
		}

		.discussionListItem .posterAvatar .miniMe
		{
			{xen:property discussionListMiniMe}
		}

			.discussionListItem .posterAvatar .miniMe img
			{
				border-radius: {xen:property avatar.border-radius};
				{xen:property discussionListMiniMeImg}				
			}		


	/* title, poster section */

	.discussionListItem .titleText
	{
		padding: 5px;
		overflow: hidden; zoom: 1;
		position: relative;
	}

		/* unread indicator */

		.LoggedIn .discussionListItem .titleText
		{			
			padding-left: 20px;
		}

			.noUnreadLinks .discussionListItem .titleText
			{
				padding-left: 5px;
			}

		.LoggedIn .discussionListItem .unreadLink,
		.LoggedIn .discussionListItem .ReadToggle
		{
			display: block;
			width: 15px;
			height: 15px;

			position: absolute;
			left: 0;
			top: 10px;

			white-space: nowrap;
			text-indent: 9999px;

			color: {xen:property primaryMedium};
		}

			.LoggedIn .discussionListItem .unreadLink:after,
			.LoggedIn .discussionListItem.unread .ReadToggle:after
			{
				position: absolute;
				top: 0;
				left: 0;
				right: 0;
				text-align: center;
				content: '\{xen:if '{$pageIsRtl}', 'f060', 'f061'}';
				font-family: 'FontAwesome';
				font-size: 11px;
				text-indent: 0;
				line-height: 1em;
			}

			.LoggedIn .discussionListItem .unreadLink:hover,
			.LoggedIn .discussionListItem .ReadToggle:hover
			{
				color: {xen:property secondaryMedium};
			}

		/* first row */

		.discussionListItem .title
		{
			{xen:property discussionListFirstRow}
			max-width: 100%;
			word-wrap: break-word;
		}

			.discussionListItems .unread .title a
			{
				{xen:property discussionListTitleUnread}
			}


		.discussionListItem .iconKey span
		{
			{xen:property dicussionListIcon}
		}

			.discussionListItem .iconKey span:after
			{
				{xen:property dicussionListIconAfter}
			}

			.discussionListItem .iconKey .sticky:after { content: '\e336'; font-family: 'Glyphicons Regular', 'Glyphicons'; font-size: 13px; }
			.discussionListItem .iconKey .starred:after { content: '\f005'; color: {xen:property secondaryMedium}; }
			.discussionListItem .iconKey .watched:after { content: '\f058'; }
			.discussionListItem .iconKey .locked:after { content: '\f023'; }
			.discussionListItem .iconKey .moderated:after { content: '\e271'; font-family: 'Glyphicons Regular', 'Glyphicons'; font-size: 12px; }
			.discussionListItem .iconKey .redirect:after { content: '\{xen:if '{$pageIsRtl}', 'f060', 'f061'}'; font-size: 14px; }
			.discussionListItem .iconKey .new:after { content: '\e246'; font-family: 'Glyphicons Regular', 'Glyphicons'; font-size: 12px; color: {xen:property secondaryMedium}; }
			.discussionListItem .iconKey .deleted:after { content: '\f00d'; }

		/* second row */

		.discussionListItem .secondRow
		{
			{xen:property discussionListSecondRow}
			clear: both;
		}

			.discussionListItem .secondRow .controls
			{
				float: right;
				padding-left: 20px;
			}

				.discussionListItem.AjaxProgress .controls
				{
					background: transparent url('{xen:property imagePath}/xenforo/widgets/ajaxload.info_B4B4DC_facebook.gif') no-repeat left center;
				}

			.discussionListItem .posterDate
			{
				float: left;
			}



	/* stats section */

	.discussionListItem .stats dl
	{
		padding: 0 10px;
	}
		.discussionListItem .stats .major
		{
			{xen:property discussionListFirstRow}

			margin-top: 5px;
		}

		.discussionListItem .stats .minor
		{
			{xen:property discussionListSecondRow}

			margin-bottom: 5px;
		}

	/* last post section */

	.discussionListItem .lastPostInfo
	{
		padding: 5px;
	}

		.discussionListItem .lastPostInfo .username
		{
			{xen:property discussionListFirstRow}
		}


			.discussionListItems .unread .lastPostInfo .username
			{
			}

		.discussionListItem .lastPostInfo .dateTime
		{
			{xen:property discussionListSecondRow}
		}


/* extra note row */

.discussionListItem .noteRow
{
	{xen:property primaryContent.background}
	padding: 5px;
	text-align: center;
	font-size: 11px;
	color: {xen:property primaryMedium};
}

	.discussionListItem .noteRow.secondary
	{
		{xen:property secondaryContent.background}
	}




/* deleted item */

.discussionList .discussionListItem.deleted
{
}

	.discussionList .discussionListItem.deleted .avatar img
	{
		opacity: 0.5;
		filter: alpha(opacity='50');
	}

	.discussionList .discussionListItem.deleted .deletionNote
	{
		float: left;
		color: {xen:property secondaryMedium};
	}

/* moderated item */

.discussionList .discussionListItem.moderated .innerBlock
{
	{xen:property discussionListItemModerated}
}

	.discussionList .discussionListItem.moderated .listBlock
	{
		background: none;
	}


/* inline mod selected/checked classes */

.discussionListItem.InlineModChecked .innerBlock
{
	{xen:property inlineModChecked}
}

	.discussionListItem.InlineModChecked .innerBlock .listBlock
	{
		background: none;
	}


/** bottom summary **/

.discussionList .sectionFooter
{
	overflow: hidden; zoom: 1;
}

	.discussionList .sectionFooter{xen:if '!{xen:property separateThreads}', '.compact'}
	{
		{xen:property primaryContent.border}

		border-width: 0;
		overflow: hidden;

		{xen:property discussionListFooter}
	}

	.discussionList .sectionFooter .contentSummary
	{
		float: left;
		display: block;
	}


/** thread list options **/

.DiscussionListOptions
{
	{xen:property discussionListOptions}
}

.hasJs .DiscussionListOptions
{
	display: none;
}

	.DiscussionListOptions dl,
	.DiscussionListOptions .controlGroup
	{
		float: left;
		margin-right: 10px;

		overflow: hidden; zoom: 1;
	}

		.DiscussionListOptions dt
		{
			float: left;
		}

		.DiscussionListOptions dd
		{
			margin-left: 120px;
		}

	.DiscussionListOptions .buttonGroup
	{
		float: right;
	}

		.DiscussionListOptions .buttonGroup input
		{
			min-width: 75px;
		}

#DiscussionListOptionsHandle
{
	{xen:property discussionListOptionsHandle}
}

	#DiscussionListOptionsHandle a
	{
		{xen:property discussionListOptionsHandleLink}
	}

.afterDiscussionListHandle
{
	margin-top: 20px;
}

/** item page nav **/

.discussionListItem .itemPageNav
{
	{xen:if '{xen:property discussionListPageNavHidden}', 'visibility: hidden;'}
}

.discussionListItem:hover .itemPageNav,
.Touch .discussionListItem .itemPageNav
{
	visibility: visible;
}

	body .itemPageNav a,
	body .itemPageNav span
	{
		{xen:property discussionListItemPageNavItem}
	}

	body .itemPageNav a
	{
		{xen:property discussionListItemPageNavLink}
	}

	body .itemPageNav a:hover
	{
		{xen:property discussionListItemPageNavLinkHover}
	}

/** filters **/

.discussionListFilters
{
	{xen:property discussionListFilters}
}

	.discussionListFilters .filtersHeading
	{
		{xen:property filtersHeading}
	}

	.discussionListFilters .removeFilter,
	.discussionListFilters .removeAllFilters
	{
		{xen:property filtersHeadingButton}
	}

		.discussionListFilters .gadget
		{
			{xen:property filtersHeadingGadget}
		}


		.discussionListFilters .removeFilter:hover,
		.discussionListFilters .removeAllFilters:hover
		{
			{xen:property filtersHeadingButtonHover}
		}

	.discussionListFilters .pairsInline dt
	{
		display: none;
	}

	.discussionListFilters .filterPairs
	{
		float: left;
	}

	.discussionListFilters .removeAll
	{
		float: right;
	}

		.discussionListFilters .removeAllFilters
		{
			padding: 2px 6px;
		}

/** compact threads **/
.discussionList .sectionHeaders.compact
{
	display: none;
}

	.discussionListWrapper + .discussionListWrapper > .sectionHeaders.compact + .discussionListItems:before
	{
		content: '';

		{xen:property primaryContent.border}

		{xen:property subHeading}

	<xen:if is="{$pageIsRtl}">
	{xen:property subHeadingRTL}
	</xen:if>

		{xen:property discussionListHeaders}

		display: none;

		{xen:property discussionListHeadersCompactReplacement}
	}

.discussionListItems.compact
{
	display: table;
	position: relative;
}

	.discussionListItems.compact + .discussionListItems.compact,
	.discussionListItems.compact + .sectionHeaders.compact + .discussionListItems.compact
	{
		margin-top: -5px;
	}

.discussionListItem.compact-thread
{
