}

	.sectionMain.mainContentBlock .event
	{
		margin: 0;
		padding: 5px;
		box-shadow: none;
		background: transparent none;
		border-width: 0;
		border-radius: 0;
		border-top: 1px solid {xen:property innerTopBorder};
		border-bottom: 1px solid {xen:property innerBottomBorder};
	}

		.sectionMain.mainContentBlock .event:first-child
		{
			border-top-width: 0;
		}

		.sectionMain.mainContentBlock .event:last-child
		{
			border-bottom-width: 0;
		}

	.event .avatar,
	.event .icon
	{
		float: left;
	}

	.event .content
	{
		margin-left: 65px;
		padding-top: 1px;
	}

		.event .NewsFeedItemHider
		{
			float: right;
			margin-left: 5px;
		}

		.event .content .description
		{
			color: {xen:property mutedTextColor};
		}

			.event .content .description em
			{
				color: {xen:property contentText};
			}

		.event .content .options
		{
			float: right;
			font-size: 11px;
		}

		.event .content .primaryText
		{
			font-weight: bold;
		}

		.event .content .title
		{
			line-height: 16px;
			margin-top: 5px;
		}

		.event .content .minorTitle
		{
			font-size: 11px;
