			margin-top: 5px;
		}

		.event .content .snippet
		{
			margin: 5px 0;

			{xen:property messageText};

			font-size: 11px;
			font-style: italic;
		}

		.event .content .DateTime
		{
			display: block;
			color: {xen:property mutedTextColor};
			font-size: 11px;
			margin-top: 5px;
		}

		.event .content .icon
		{
			display: inline-block;
			width: 16px;
			height: 16px;
			margin-right: 5px;
			vertical-align: middle;
		}

		.event .content .thread .icon,
		.event .content .forum .icon
		{
			position: relative;
		}

			.event .content .thread .icon:after,
			.event .content .forum .icon:after
			{
				font-size: 1em;
