				display: block;
				content: '\f086';
				font-weight: normal;
				position: absolute;
				left: 0;
				right: 0;
				top: -1px;
				text-align: center;
				color: inherit;
			}

			.event .content .thread .icon:after
			{
				font-size: .8em;
				content: '\f075';
				top: 0;
			}

		.event .content .attachedImages		
		{
		}

			.event .content .attachedImages:hover,
			.event .content .attachedImages:active
			{
				outline: 0 none;
				text-decoration: none;
			}

				.event .content .attachedImages img
				{
					max-height: 32px;
				}

#recentAttachments { position: relative; padding: 5px 30px; }
#recentAttachments .carousel-frame { margin: 0 auto; }

#recentAttachments ul { overflow: hidden; }

#recentAttachments .carouselButton
{
	color: {xen:property link.color};
	position: absolute; 
	top: 50%;
	font-size: 24px;
	line-height: 24px;
	width: 26px;
	height: 26px;
	margin: -13px 0 0;
	cursor: pointer;
	overflow: hidden;
	text-indent: 999px;
	opacity: .7;
	text-decoration: none !important;
}
#recentAttachments .carouselButton:after
{
	position: absolute;
	left: 0;
	right: 0;
	top: 1px;
	content: '\f0a8';
	font-family: FontAwesome;
	color: inherit;
	font-size: inherit;
	text-indent: 0;
	font-weight: normal;
	font-style: normal;
	text-align: center;
	pointer-events: none;
}
#recentAttachments .carouselButton:hover { color: {xen:property linkHover.color}; opacity: 1; }
#recentAttachments .carouselButton.prev { left: 3px;  }
#recentAttachments .carouselButton.next { right: 3px; }
#recentAttachments .carouselButton.next:after { content: '\f0a9'; }

{xen:helper clearfix, 'ul.attachmentsFull'}
.recentAttachments li { float: left; }

.recentAttachments .imageCropper { }
.recentAttachments .imageCropper:hover { }
.recentAttachments .imageMeta { display: none; }

.recentAttachments .imageHolder
{
	overflow: hidden;
	background-position: center center;
	background-repeat: no-repeat;
	position: relative;
}
.recentAttachments .imageHolder img { opacity: 0; }
.recentAttachments .imageHolder.imageHorz { background-size: 100% auto; }
.recentAttachments .imageHolder.imageVert { background-size: auto 100%; }


/*---------------------------------------*/
/* DO NOT TOUCH ANYTHING BELOW THIS LINE */
/*---------------------------------------*/

.recentAttachments .imageCropper { padding: 2px; margin: 2px; }

#recentAttachments ul { height: 116px; } /*HEIGHT*/
#recentAttachments .imageHolder,
#recentAttachments .imageHolder img { height: 106px; width: 106px; } /*WIDTH*/

.recentAttachments ul { height: 115px; } /*FULLHEIGHT*/
.recentAttachments .imageHolder,
.recentAttachments .imageHolder img { height: 105px; width: 105px; } /*FULLWIDTH*/

.recentNews .subHeading { margin-bottom: 10px; }
.recentNews .subHeading a { color: {xen:property subHeading.color}; }
.recentNews .subHeading h2 { font-size: 1.5em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.recentNews .subHeading > div { margin-top: 3px; }
.recentNews .messageUserBlock { float: right; margin-left: 10px; }

.recentNews .newsDate { float: left; margin: 0px 10px 10px 0px; padding: 0px 10px 5px; width: 35px; font-weight: bold; text-align: center; }
.recentNews .newsDate .newsMonth { padding: 10px 0px 5px !important; margin: 0px -10px 5px !important; text-transform: uppercase; }
.recentNews .newsDate .newsDay { font-size: 26px; }

.recentNews .leftDate .newsDate { 
	background: {xen:property blocksInnerBackground};
	border-width: 0;
	border-radius: {xen:property primaryContent.border-radius};
	overflow: hidden;
}
.recentNews .leftDate .newsText { margin-left: 25px; }

.recentNews .messageContent { font-size: 13px; }
.recentNews .messageContent .postedBy { margin-bottom: 10px; }
.recentNews .messageContent .username { font-weight: bold; }
.recentNews .messageContent .comments { float: right; font-weight: bold; }
.recentNews .messageContent .clearFix { clear: right; }

.recentNews .messageUserBlock div.avatarHolder { margin-bottom: {xen:property messageAvatarHolder.margin-top}; }

.recentNews .iconKey div
{
	color: {xen:property mutedTextColor};
	width: 16px;
	height: 16px;
	float: left;
	margin-right: 4px;
	position: relative;
}
.recentNews .iconKey div:after
{
	{xen:property dicussionListIconAfter}
}

.recentNews .iconKey .sticky:after { content: '\e336'; font-family: 'Glyphicons Regular', 'Glyphicons'; font-size: 13px; }
.recentNews .iconKey .redirect:after { content: '\E223'; font-family: 'Glyphicons Regular', 'Glyphicons'; font-size: 13px; color: {xen:property primaryLightest}; }
.recentNews .iconKey .new:after { content: '\e246'; font-family: 'Glyphicons Regular', 'Glyphicons'; font-size: 12px; color: {xen:property secondaryMedium}; }

.recentNews .sectionFooter { margin: 0; padding: 5px 0 0; text-align: right; position: relative; background: none; border-width: 0; border-radius: 0; box-shadow: none; }
.recentNews .sectionFooter .continue { padding-top: 5px; font-size: 12px; }
.recentNews .sectionFooter .continue .redirect { margin: 3px 4px 0px 0px; }

.recentNews .sectionFooter .categories { padding-top: 5px; float: left; }
.recentNews .sectionFooter .categories li { display: inline; }

.recentNews .sectionFooter .sharePage { position: absolute; }
.recentNews .sectionFooter .shareControl { margin-top: 6px !important; }

.leftContainer { float: right; margin-left: -{xen:calc '{xen:property sidebar.width} + 10'}px; width: 100%; }
.leftContent { margin-left: {xen:calc '{xen:property sidebar.width} + 10'}px; }
.leftSidebar { float: left; }

.splitWidgets .section:first-child,
.splitWidgets .sectionMain:first-child { margin-top: 0; }

.sidebar.noFloats { float: none; width: auto; margin-bottom: 10px; }
.sidebar.b-rightWidgets { margin-left: {xen:calc '{xen:property sidebar.width} + 10'}px; }
.sidebar.b-leftWidgets { float: left; }
.sidebar.footerWidgets { clear: both; }
{xen:helper clearfix, '.splitWidgets'}

.copyright { text-align: center; font-size: 11px; margin: 10px; }

<xen:if is="{xen:property enableResponsive}">
	@media (max-width:{xen:property maxResponsiveWideWidth})
	{
		.Responsive .leftContainer { float: none; margin: 0 auto; }
		.Responsive .leftContent { margin-left: 0; }
	}
	@media (max-width:{xen:property maxResponsiveMediumWidth})
	{
		.Responsive .sidebar.b-leftWidgets { float: none; margin: 0 auto; }
		.Responsive .sidebar.b-rightWidgets { margin-left: 0px; }
	}
</xen:if>


