		border-bottom: 1px solid {xen:property innerBottomBorder};
	}

	.articleItem div.sectionFooter
	{
		padding: 5px;
		border-top: 1px solid {xen:property innerTopBorder};
	}

.articleItem div.dateBlock
{
	margin-left: 0;
	margin-top: 5px;
	z-index: 2;
}

	.articleItem div.dateBlock .heading
	{
		border-bottom-left-radius: 0;
		border-bottom-right-radius: 0;
		box-shadow: none;
	}

	.articleItem div.dateBlock .secondaryContent
	{
		border-top-left-radius: 0;
		border-top-right-radius: 0;
		background-color: {xen:property blocksInnerBackground};
		box-shadow: none;
	}

.articleItem div.metaData
{
	border-bottom-color: {xen:property innerTopBorder};
	position: relative;
}

	.articleItem div.metaData:after
	{
		content: '';
		display: block;
		position: absolute;
		left: 0;
		right: 0;
		bottom: 0;
		border-bottom: 1px dashed {xen:property innerBottomBorder};
	}


.articleItem .iconKey,
.iconKey.category
{
	{xen:property dicussionListIcon}

	float: left;
	margin: 0 4px 0 0;
	background: none;
	position: relative;
}

	.articleItem .iconKey:after,
	.iconKey.category:after
	{
		{xen:property dicussionListIconAfter}
	}

	.articleItem .iconKey.category:after, .iconKey.category:after { content: '\{xen:if '{$pageIsRtl}', 'f0a8', 'f0a9'}'; top: 1px; }
	.articleItem .iconKey.sticky:after { content: '\e336'; font-family: 'Glyphicons Regular', 'Glyphicons'; font-size: 13px; }
	.articleItem .iconKey.redirect:after { content: '\{xen:if '{$pageIsRtl}', 'f060', 'f061'}'; font-size: 14px; }
	.articleItem .iconKey.comments:after { content: '\f075'; font-size: 14px; }
	.articleItem .iconKey.views:after { content: '\f06e'; }


	.button .iconKey { display: none; }
	.button .iconKey.category { display: block; color: inherit; }

.tagList .tags li div.text { background-color: {xen:property primaryMedium}; }
.tagList .tags li div.arrow { border-right-color: {xen:property primaryMedium}; }

.tagList .tags li div.text { background-color: {xen:property primaryMedium}; }
.tagList .tags li div.arrow { border-right-color: {xen:property primaryMedium}; }
.tagList .tags li:hover div.text { background-color: {xen:property secondaryMedium}; }
.tagList .tags li:hover div.arrow { border-right-color: {xen:property secondaryMedium}; }

.footer .pageContent
{
	{xen:property footer}
}

	.footer a,
	.footer a:visited
	{
		{xen:property footerLink}
	}

		.footer a:hover,
		.footer a:active
		{
			{xen:property footerLinkHover}
		}

	.footer .choosers
	{
		{xen:property footerLeftBlock}
	}

		.footer .choosers dt
		{
			display: none;
		}

		.footer .choosers dd
		{
			float: left;
			<xen:if is="{$pageIsRtl}">*display: inline; *float: none; *zoom: 1;</xen:if>
		}

	.footerLinks
	{
		{xen:property footerRightBlock}
	}

		.footerLinks li
		{
			float: left;
			<xen:if is="{$pageIsRtl}">*display: inline; *float: none; *zoom: 1;</xen:if>
		}

			.footerLinks a.globalFeed,
			.footerLinks a.homeLink,
			.footerLinks a.topLink
			{
				width: 14px;
				height: 14px;
				display: block;
				position: relative;
				text-indent: -9999px;
				white-space: nowrap;
				padding: 0;
				margin: 5px;
			}

				.footerLinks a.globalFeed:after,
				.footerLinks a.homeLink:after,
				.footerLinks a.topLink:after
				{
					content: '\f09e';
					font-family: 'FontAwesome';
					font-size: 12px;
					text-indent: 0;
					position: absolute;
					top: 0;
					left: 0;
					right: 0;
					text-align: center;
					line-height: 14px;
				}

				.footerLinks a.homeLink:after
				{
					<xen:if is="{xen:property breadCrumbHomeIconFA}">
					content: '\f015';
					<xen:else />
					content: '\e021';
					font-family: 'Glyphicons Regular', 'Glyphicons';
					font-size: 10px;
					</xen:if>
				}

				.footerLinks a.topLink:after
				{
					content: '\f0aa';
				}

.footerLegal .pageContent
{
	font-size: 11px;
	overflow: hidden; zoom: 1;
	padding: 0 5px 10px;
	text-align: center;
}

	.globalWrapper .footerLegal .pageContent
	{
		padding-bottom: 0;
	}

	#copyright
	{
		color: {xen:property dimmedTextColor};
		float: left;
	}

	#legal
	{
		float: right;
	}

		#legal li
		{
			float: left;
			<xen:if is="{$pageIsRtl}">*display: inline; *float: none; *zoom: 1;</xen:if>
			margin-left: 10px;
		}

<xen:if is="{xen:property useFooterWidgetsLayout}">
.pageFooter
{
	{xen:property footerWrapper}
}

.footerWrapper
{
	{xen:property footerOuterWrapper}
}

	.footerWrapperInner
	{
		{xen:property footerInnerWrapper}
	}

.footerWrapperOuter
{
	{xen:property footerWrappedWrapper}
}

.pageFooter #copyright,
.pageFooter .pairs dt, 
.pageFooter .pairsInline dt, 
.pageFooter .pairsRows dt, 
.pageFooter .pairsColumns dt, 
.pageFooter .pairsJustified dt
{
	color: inherit;
}

.pageFooter a
{
	{xen:property advFooterLink}
}

	.pageFooter a:hover
	{
		{xen:property advFooterLinkHover}
	}

	.pageFooter a:active
	{
		{xen:property advFooterLinkActive}
	}

<xen:if is="{xen:property enableResponsive}">

<xen:if is="{xen:property globalWrapper} && ({xen:property pageWidth.width} > 0 || {xen:property maxPageWidth})">
<xen:if is="{xen:property maxPageWidth}">
@media (max-width:{xen:calc '{xen:property maxPageWidth} + {xen:property globalWrapperLayout.padding-left} + {xen:property globalWrapperLayout.padding-right}'}px)
<xen:else />
@media (max-width:{xen:calc '{xen:property pageWidth.width} + {xen:property globalWrapperLayout.padding-left} + {xen:property globalWrapperLayout.padding-right}'}px)
</xen:if>
{
	.Responsive .footerWrapperOuter
	{
		{xen:property footerWrappedWrapperFixed}
	}
}
</xen:if>
@media (max-width:{xen:property maxResponsiveWideWidth})
{
	.Responsive .footerWrapperOuter
	{
		{xen:property footerWrappedWrapperMobile}
	}
}
</xen:if>

</xen:if>

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveMediumWidth})
{
	.Responsive .footerLinks a.globalFeed,
	.Responsive .footerLinks a.topLink,
	.Responsive .footerLinks a.homeLink
	{
		display: none;
	}

	.Responsive .footerLegal .debugInfo
	{
		clear: both;
	}
}

@media (max-width:{xen:property maxResponsiveNarrowWidth})
{
	.Responsive #copyright span
	{
		display: none;
	}
}
</xen:if>

/** Forms **/

.xenForm
{
	margin: 10px auto;
	max-width: {xen:property formWidth};
}

	.xenOverlay .xenForm
	{
		max-width: {xen:property overlayFormWidth};
	}

.xenForm .ctrlUnit > dd
{
	width: {xen:property ctrlUnitValueWidth};
	box-sizing: border-box;
	padding-right: {xen:property ctrlUnitEdgeSpacer};
}

.xenForm .ctrlUnit > dd .textCtrl
{
	box-sizing: border-box;
	width: 100%;
}

	.xenForm .ctrlUnit > dd .textCtrl[size],
	.xenForm .ctrlUnit > dd .textCtrl.autoSize
	{
		width: auto !important;
		min-width: 0;
	}

	.xenForm .ctrlUnit > dd .textCtrl.number
	{
		width: 150px;
	}


.xenForm > .sectionHeader:first-child,
.xenForm > fieldset > .sectionHeader:first-child
{
	margin-top: 0;
}

/** Sections **/

.xenForm fieldset,
.xenForm .formGroup
{
	border-top: 1px solid {xen:property innerBottomBorder};
	margin: 20px auto;
	position: relative;
	padding-top: 1px;
}

	.xenForm fieldset:before,
	.xenForm .formGroup:before
	{
		content: '';
		position: absolute;
		top: 0;
		left: 0;
		right: 0;
		border-top: 1px solid {xen:property innerTopBorder};
	}

.xenForm > fieldset:first-child,
.xenForm > .formGroup:first-child
{
	border-top: none;
	margin: auto;
	padding-top: 0;
}

	.xenForm > fieldset:first-child:before,
	.xenForm > .formGroup:first-child:before
	{
		display: none;
	}

.xenForm .PreviewContainer + fieldset,
.xenForm .PreviewContainer + .formGroup
{
	border-top: none;
	padding-top: 0;
}

	.xenForm .PreviewContainer + fieldset:before,
	.xenForm .PreviewContainer + .formGroup:before
	{
		display: none;
	}

.xenForm fieldset + .ctrlUnit,
.xenForm .formGroup + .ctrlUnit,
.xenForm .submitUnit
{
	border-top: 1px solid {xen:property innerBottomBorder};
	position: relative;
	padding-top: 1px;
}

	.xenForm fieldset + .ctrlUnit:before,
	.xenForm .formGroup + .ctrlUnit:before,
	.xenForm .submitUnit:before
	{
		content: '';
		position: absolute;
		top: 0;
		left: 0;
		right: 0;
		border-top: 1px solid {xen:property innerTopBorder};
	}


.xenForm fieldset + .ctrlUnit,
.xenForm .formGroup + .ctrlUnit
{
	padding-top: 11px;
}

.xenForm .primaryContent + .submitUnit,
.xenForm .secondaryContent + .submitUnit
{
	margin-top: 0;
	border-top: none;
}

	.xenForm .primaryContent + .submitUnit:before,
	.xenForm .secondaryContent + .submitUnit:before
	{
		display: none;
	}

.xenForm .ctrlUnit.submitUnit dd
{	
	line-height: 31px;
	padding-top: 0;
}

	.ctrlUnit.submitUnit dd .explain,
	.ctrlUnit.submitUnit dd .text,
	.ctrlUnit.submitUnit dd label
	{
		line-height: 1.28;
	}

/* now undo that */

.xenOverlay .ctrlUnit.submitUnit dd,
.Menu .ctrlUnit.submitUnit dd,
#QuickSearch .ctrlUnit.submitUnit dd
{
	border: none;
	background: none;
}

.xenForm .ctrlUnit
{
	{xen:property ctrlUnit}
}

	.xenForm .ctrlUnit.limited
	{
		display: none;
	}

	.xenForm .ctrlUnit.submitUnit
	{
		padding-top: 5px;
	}

	/** Sections Immediately Following Headers **/

	.xenForm .sectionHeader + fieldset,
	.xenForm .heading + fieldset,
	.xenForm .subHeading + fieldset,
	.xenForm .sectionHeader + .formGroup,
	.xenForm .heading + .formGroup,
	.xenForm .subHeading + .formGroup
	{
		border-top: none;
		margin-top: 0;
	}

		.xenForm .sectionHeader + fieldset:before,
		.xenForm .heading + fieldset:before,
		.xenForm .subHeading + fieldset:before,
		.xenForm .sectionHeader + .formGroup:before,
		.xenForm .heading + .formGroup:before,
		.xenForm .subHeading + .formGroup:before
		{
			display: none;
		}

.xenForm .formHiderHeader
{
	margin: 10px;
	font-size: 15px;
	font-weight: bold;
}


/** *********************** **/
/** TEXT INPUTS             **/
/** *********************** **/

.textCtrl
{
	-webkit-border-radius: 0;
	-webkit-appearance: none;

	{xen:property textCtrl}
}

select.textCtrl
{
	word-wrap: normal;
	-webkit-appearance: menulist;
}

select[multiple].textCtrl,
select[size].textCtrl
{
	-webkit-appearance: listbox;
}

select[size="0"].textCtrl,
select[size="1"].textCtrl
{
	-webkit-appearance: menulist;
}

textarea.textCtrl
{
	word-wrap: break-word;
}

	.textCtrl:hover,
	.textCtrl.Hover
	{
		{xen:property textCtrlHover}
	}	

	.textCtrl:focus,
	.textCtrl.Focus
	{
		{xen:property textCtrlFocus}
	}	

	textarea.textCtrl:focus
	{
		{xen:property textCtrlTextareaFocus}
	}

	input.textCtrl.disabled,
	textarea.textCtrl.disabled,
	.disabled .textCtrl
	{
		{xen:property textCtrlDisabled}
	}

	.textCtrl.prompt
	{
		{xen:property formElementPrompt}
	}

	.textCtrl:-moz-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPrompt}
	}

	.textCtrl::-moz-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPrompt}
	}

	.textCtrl::-webkit-input-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPrompt}
	}

	.textCtrl:-ms-input-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPrompt}
	}

	.textCtrl.prompt:hover
	{
		{xen:property formElementPromptHover}
	}

	.textCtrl:hover:-moz-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPromptHover}
	}

	.textCtrl:hover::-moz-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPromptHover}
	}

	.textCtrl:hover::-webkit-input-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPromptHover}
	}

	.textCtrl:hover:-ms-input-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPromptHover}
	}

	.textCtrl.prompt:focus
	{
		{xen:property formElementPromptFocus}
	}

	.textCtrl:focus:-moz-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPromptFocus}
	}

	.textCtrl:focus::-moz-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPromptFocus}
	}

	.textCtrl:focus::-webkit-input-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPromptFocus}
	}

	.textCtrl:focus:-ms-input-placeholder
	{
		/* needs to be in its own rule due to weird selector */
		{xen:property formElementPromptFocus}
	}

	.textCtrl:invalid
	{
		{xen:property formElementInvalid}
	}

	.textCtrl:-moz-submit-invalid
	{
		{xen:property formElementInvalid}
	}

	.textCtrl:-moz-ui-invalid
	{
		{xen:property formElementInvalid}
	}

	.textCtrl.autoSize
	{
		width: auto !important;
	}

	.textCtrl.number,
	.textCtrl.number input
	{
		text-align: right;
		width: 150px;
	}

	.textCtrl.fillSpace
	{
		width: 100%;
		box-sizing: border-box;
		_width: 95%;
	}

	.textCtrl.code,
	.textCtrl.code input
	{
		{xen:property textCtrlCode}
	}

	input.textCtrl[type="password"]
	{
		font-family: Verdana, Geneva, Arial, Helvetica, sans-serif;
	}

	input[type="email"],
	input[type="url"]
	{
		direction: ltr;
	}

	input[type="search"]
	{
		-webkit-appearance: none;
	}

	input[type="search"]::-webkit-search-decoration,
	input[type="search"]::-webkit-search-results-button,
	input[type="search"]::-webkit-search-results-decoration
	{
		display: none;
	}

	.textCtrl.titleCtrl,
	.textCtrl.titleCtrl input
	{
		font-size: 18pt;
	}

textarea.textCtrl.Elastic
{
	/* use for jQuery.elastic */
	max-height: 300px;
}

	.sidebar textarea.textCtrl.Elastic
	{
		max-width: 97%;
	}

/* for use with wrapped inputs */
.textCtrlWrap
{
	display: inline-block;
}

.textCtrlWrap input.textCtrl
{
	padding: 0 !important;
	margin: 0 !important;
	border: none !important;
	background: transparent !important;
	border-radius: 0 !important;
}

.textCtrlWrap.blockInput input.textCtrl
{
	border-top: {xen:property textCtrl.border-top-width} {xen:property textCtrl.border-top-style} {xen:property textCtrl.border-top-color} !important;
	margin-top: 4px !important;
}

/** *********************** **/
/** BUTTONS                 **/
/** *********************** **/

.button
{
	font-style: normal;
	-webkit-appearance: none;

	{xen:property button}
}

.button.smallButton
{
	font-size: 11px;
	padding: 0px 4px;
	line-height: 21px;
	height: 21px;
	border-radius: 5px;
}

.button.primary
{
	{xen:property buttonPrimary}
}

input.button.disabled,
a.button.disabled,
input.button.primary.disabled,
a.button.primary.disabled,
html .buttonProxy .button.disabled
{
	{xen:property buttonDisabled}
}

	.button::-moz-focus-inner
	{
		border: none;
	}

	a.button
	{
		display: inline-block;
		color: {xen:property button.color};
	}

	.button:hover,
	.button[href]:hover,
	.buttonProxy:hover .button
	{
		{xen:property buttonHover}
	}

	.button:focus
	{
		{xen:property buttonFocus}
	}

	.button:active,
	.button[href]:active,
	.button.ToggleButton.checked,
	.buttonProxy:active .button
	{
		{xen:property buttonActive}
	}

	.button.ToggleButton
	{
		{xen:property buttonToggle}
	}

	.button.ToggleButton.checked
	{
		{xen:property buttonToggleChecked}
	}

	.button.inputSupplementary
	{
		width: 25px;
		position: absolute;
		top: 0px;
		right: 0px;
	}

	.button.inputSupplementary.add
	{
		color: green;
	}

	.button.inputSupplementary.delete
	{
		color: red;
	}

	.submitUnit .button
	{
		min-width: 100px;
		*min-width: 0;
	}

















/** Control Units **/

.xenForm .ctrlUnit
{
	position: relative;
	margin: 10px auto;
}

{xen:helper clearfix, '.xenForm .ctrlUnit'}

.xenForm .ctrlUnit.fullWidth
{
	overflow: visible;
}

/** Control Unit Labels **/

.xenForm .ctrlUnit > dt
{
	{xen:property ctrlUnitLabel}
	box-sizing: border-box;
	width: {xen:property ctrlUnitLabelWidth};
	float: left;
}

/* special long-text label */
.xenForm .ctrlUnit > dt.explain
{
	font-size: 11px;
	text-align: justify;
}


.xenForm .ctrlUnit.fullWidth dt,
.xenForm .ctrlUnit.submitUnit.fullWidth dt
{
	float: none;
	width: auto;
	text-align: left;
	height: auto;
}

.xenForm .ctrlUnit.fullWidth dt
{
	margin-bottom: 2px;
}

	.xenForm .ctrlUnit > dt label
	{
		margin-left: {xen:property ctrlUnitEdgeSpacer};
	}

	/** Hidden Labels **/

	.xenForm .ctrlUnit.surplusLabel dt label
	{
		display: none;
	}

	/** Section Links **/

	.ctrlUnit.sectionLink dt
	{
		text-align: left;
		font-size: 11px;
	}

		.ctrlUnit.sectionLink dt a
		{
			margin-left: {xen:calc '10 + 1'}px; /*TODO: sectionHeader padding + border*/
		}		

	/** Hints **/

	.ctrlUnit > dt dfn
	{
		{xen:property ctrlUnitLabelHint}
	}

	.ctrlUnit.fullWidth dt dfn
	{
		display: inline;
		margin: 0;
	}

		.ctrlUnit > dt dfn b,
		.ctrlUnit > dt dfn strong
		{
			color: {xen:property dimmedTextColor};
		}

	/** Inline Errors **/

	.ctrlUnit > dt .error
	{
		{xen:property ctrlUnitLabelError}
	}

	.ctrlUnit > dt dfn,
	.ctrlUnit > dt .error,
	.ctrlUnit > dt a
	{
		font-weight: normal;
	}

.xenForm .ctrlUnit.submitUnit dt
{
	height: 19px;
	display: block;
}

	.ctrlUnit.submitUnit dt.InProgress
	{
		background: transparent url('{xen:property imagePath}/xenforo/widgets/ajaxload.info_B4B4DC_facebook.gif') no-repeat center center;
	}

/** Control Holders **/

.xenForm .ctrlUnit > dd
{
	/*todo: kill property */
	{xen:property ctrlUnitCtrl}
	float: left;
}

.xenForm .ctrlUnit.fullWidth > dd
{
	float: none;
	width: auto;
	padding-left: {xen:property ctrlUnitEdgeSpacer};
}

/** Explanatory paragraph **/

.ctrlUnit > dd .explain
{
	{xen:property ctrlUnitCtrlExplain}
	/*TODO:max-width: auto;*/
}

	.ctrlUnit > dd .explain b,
	.ctrlUnit > dd .explain strong
	{
		color: {xen:property dimmedTextColor};
	}

/** List items inside controls **/

.ctrlUnit > dd > * > li
{
	margin: 4px 0 8px;
	padding-left: 1px; /* fix a webkit display bug */
}

.ctrlUnit > dd > * > li:first-child > .textCtrl:first-child
{
	margin-top: -3px;
}

.ctrlUnit > dd .break
{
	margin-bottom: 0.75em;
	padding-bottom: 0.75em;
}

.ctrlUnit > dd .rule
{
	border-bottom: 1px solid {xen:property primaryLighterStill};
}

.ctrlUnit > dd .ddText
{
	margin-bottom: 2px;
}

/** Hints underneath checkbox / radio controls **/

.ctrlUnit > dd > * > li .hint
{
	font-size: 11px;
	color: {xen:property mutedTextColor};
	margin-left: {xen:property formCtrlIndent};
	margin-top: 2px;
}

/** DISABLERS **/

.ctrlUnit > dd > * > li > ul,
.ctrlUnit .disablerList,
.ctrlUnit .indented
{
	margin-left: {xen:property formCtrlIndent};
}

.ctrlUnit > dd > * > li > ul > li:first-child
{
	margin-top: 6px;
}

.ctrlUnit > dd .disablerList > li,
.ctrlUnit > dd .checkboxColumns > li,
.ctrlUnit > dd .choiceList > li
{
	margin-top: 6px;
}

/** Other stuff... **/

.ctrlUnit > dd .helpLink
{
	font-size: 10px;
}

.ctrlUnit.textValue dt
{
	padding-top: 0px;
}

.button.spinBoxButton
{
	font-family: {xen:property body.font-family};
	{xen:property spinBoxButton}
}

.unitPairsJustified li
{
	overflow: hidden;
}

	.unitPairsJustified li .label
	{
		float: left;
