#calroot
{
	{xen:property calRoot}
}

#calhead
{	
	padding: 2px 0;
	height: 22px;
} 

	#caltitle {
		font-size: 11pt;
		color: {xen:property primaryMedium};
		float: left;
		text-align: center;
		width: 155px;
		line-height: 20px;
	}

	#calnext, #calprev {
		display: block;
		width: 20px;
		height: 20px;
		font-size: 11pt;
		line-height: 20px;
		text-align: center;
		float: left;
		cursor: pointer;
	}

	#calnext {
		float: right;
	}

	#calprev.caldisabled, #calnext.caldisabled {
		visibility: hidden;	
	}

#caldays {
	height: 14px;
	border-bottom: 1px solid {xen:property blocksInnerBorder};
}

	#caldays span {
		display: block;
		float: left;
		width: 28px;
		text-align: center;
		color: {xen:property primaryMedium};
	}

#calweeks {
	margin-top: 4px;
}

.calweek {
	clear: left;
	height: 22px;
}

	.calweek a {
		display: block;
		float: left;
		width: 27px;
		height: 20px;
		text-decoration: none;
		font-size: 11px;
		margin-left: 1px;
		text-align: center;
		line-height: 20px;
		border-radius: {xen:property floatingNavLayout.border-radius};
	} 

		.calweek a:hover, .calfocus {
			background-color: {xen:property primaryLightest};
		}

a.caloff {
	color: {xen:property mutedTextColor};		
}

a.caloff:hover {
	background-color: {xen:property primaryLightest};		
}

a.caldisabled {
	background-color: #efefef !important;
	color: #ccc	!important;
	cursor: default;
}

#caltoday {
	font-weight: bold;
}

#calcurrent {
	background-color: {xen:property primaryDark};
	color: {xen:property primaryLightest};
}

#header
{
	position: relative;
	{xen:property header}

	{xen:property headerExtra}
}

{xen:helper clearfix, '#header .pageWidth .pageContent'}

	#logoBlock .pageWidth
	{
		position: relative;
	}

	#logo
	{
		display: block;
		<xen:if is="{xen:property centerLogo} == '1'">
		text-align: center;
		<xen:else />
		text-align: left;
		</xen:if>
		line-height: {xen:calc '{xen:property headerLogoHeight} - 4'}px;
		*line-height: {xen:property headerLogoHeight};
		height: {xen:property headerLogoHeight};
		max-width: 100%;
		vertical-align: middle;
	}

		<xen:if is="{xen:property enableAlternativeNavigation}">
			<xen:set var="$responsiveLogoWidth">{xen:calc '{xen:property headerLogoWidth} + 150'}</xen:set>
			<xen:if is="{$responsiveLogoWidth} < {xen:calc '{xen:property maxResponsiveMediumWidth} + 0'}">
				<xen:set var="$responsiveLogoWidth">{xen:calc '{xen:property maxResponsiveMediumWidth} + 0'}</xen:set>
			</xen:if>
			@media (min-width: {$responsiveLogoWidth}px)
			{
				.altNav #logo
				{
					text-align: left;
					float: left;
				}
			}
		</xen:if>

		<xen:if is="{xen:calc '{xen:property centerLogo} + 1'} > 2">
		@media (max-width: {xen:property centerLogo})
		{
			#logo
			{
				text-align: center;
			}
		}
		</xen:if>


		/* IE6/7 vertical align fix */
		#logo span
		{
			*display: inline-block;
			*height: 100%;
			*vertical-align: bottom;
		}

		<xen:if is="{xen:property headerLogoWidth}">
		#logo
		{
			height: auto;
			line-height: 1em;
		}

		#logo a
		{
			display: inline-block;
			vertical-align: bottom;
			text-decoration: none !important;
			outline: none !important;
			width: {xen:property headerLogoWidth};
			height: {xen:property headerLogoHeight};
			background: url("{xen:property headerLogoPath}") 50% 50% no-repeat;
			-webkit-background-size: {xen:property headerLogoWidth} {xen:property headerLogoHeight};
			background-size: {xen:property headerLogoWidth} {xen:property headerLogoHeight};
		}

		#logo a img
		{
			display: none;
		}

		<xen:if is="{xen:property headerLogoPathHD}">
		@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi), (min-resolution: 1.5dppx)
		{
			#logo a
			{
				background-image: url("{xen:property headerLogoPathHD}");
			}
		}
		</xen:if>

		@media (max-width: {xen:property headerLogoWidth})
		{
			#logo
			{
				float: none;
			}

			#logo a
			{
				display: block;
				margin: 0 auto;
				max-width: {xen:property headerLogoWidth};
				width: 100%;
				<xen:if is="{xen:property scaleLogo}">
				-webkit-background-size: contain;
				background-size: contain;
				</xen:if>
			}

			<xen:if is="{xen:property scaleLogo} && {xen:property scaleHeaderWithLogo}">
				#logo a
				{
					height: auto;
				}

				#logo a img
				{
					display: block;
					max-width: 100%;
					width: auto !important;
					height: auto !important;
					opacity: 0;
				}
			</xen:if>
		}

		<xen:else />
		#logo a:hover
		{
			text-decoration: none;
		}

		#logo img
		{
			vertical-align: middle;
			max-width: 100%;
		}
		</xen:if>

	#visitorInfo
	{
		float: right;
		min-width: 250px;
		_width: 250px;
		overflow: hidden; zoom: 1;
		background: {xen:property primaryLighter};
		padding: 5px;
		border-radius: 5px;
		margin: 10px 0;
		border: 1px solid {xen:property primaryDarker};
		color: {xen:property primaryDarker};
	}

		#visitorInfo .avatar
		{
			float: left;
			display: block;
		}

			#visitorInfo .avatar .img
			{
				border-color: {xen:property primaryLightish};
			}

		#visitorInfo .username
		{
			font-size: 18px;
			text-shadow: 1px 1px 10px white;
			color: {xen:property primaryDarker};
			white-space: nowrap;
			word-wrap: normal;
		}

		#alerts
		{
			zoom: 1;
		}

		#alerts #alertMessages
		{
			padding-left: 5px;
		}

		#alerts li.alertItem
		{
			font-size: 11px;
		}

			#alerts .label
			{
				color: {xen:property primaryDarker};
			}

