.xenOverlay.lightBox
{
	width: 95%;
	max-width: none;
}

	.xenOverlay.lightBox .formOverlay
	{
		padding: 0;
		border: none;
		border-radius: 10px;
		background: none;

		<xen:if is="!{xen:property primaryContent.border-top-left-radius}">
		border-radius: 0;
		</xen:if>
	}

		.xenOverlay.lightBox #LbUpper,
		.xenOverlay.lightBox #LbLower
		{
			{xen:property formOverlay.background}
		}

		.Touch .xenOverlay.lightBox #LbUpper,
		.Touch .xenOverlay.lightBox #LbLower
		{
			background-color: {xen:helper unrgba, {xen:property formOverlay.background-color}};
		}

		<xen:if is="{xen:property primaryContent.border-top-left-radius}">
		.xenOverlay.lightBox #LbUpper
		{
			border-top-left-radius: 10px;
			border-top-right-radius: 10px;
		}

		.xenOverlay.lightBox #LbLower
		{
			border-bottom-left-radius: 10px;
			border-bottom-right-radius: 10px;
		}
		</xen:if>

.lightBox a
{
	cursor: pointer;
}

.lightBox a.close
{
	right: -15px;
	top: -15px;
}

/* -------------- */

.lightBox .userInfo
{
	overflow: hidden; zoom: 1;
	padding: 10px;
	padding-bottom: 5px;
}

.lightBox .avatar
{
	float: left;
}

	.lightBox .avatar img
	{
		width: 36px;
		height: 36px;
	}

.lightBox .userText
{
	margin-left: 47px;
}

.lightBox .userTextUpper,
.lightBox .userTextLower
{
	overflow: hidden; zoom: 1;
}

	.lightBox .userTextUpper
	{
		line-height: 25px;
		font-size: 15pt;
	}

		.lightBox #LbUsername
		{
			float: left;
		}

		.lightBox .gadgets
		{
			float: right;
			overflow: hidden; zoom: 1;
		}

			.lightBox .gadgets a
			{
				float: left;
				margin-left: 3px;
				display: block;
				width: 25px;
				height: 25px;
				outline: 0 none;
				position: relative;
				color: inherit;
			}

				.lightBox .gadgets a:after
				{
					content: '\f14c';
					font-family: FontAwesome;
					font-weight: normal;
					font-style: normal;
					font-size: 23px;
					line-height: 23px;
					position: absolute;
					left: 1px;
					right: 1px;
					width: 23px;
					height: 23px;
					text-align: center;
					vertical-align: middle;
					pointer-events: none;
				}

				.lightBox .gadgets a span
				{
					display: none;
				}

				.lightBox .gadgets a.OverlayCloser:after
				{
					content: '\f00d';
				}

	.lightBox .userTextLower
	{
		font-size: 11px;
		margin-top: 2px;
	}

		.lightBox #LbDateTime
		{
			float: left;
		}

		.lightBox #LbContentLink
		{
			float: right;
		}

/* -------------- */

.lightBox .imageContainer
{
	clear: both;
	position: relative;
	min-height: 40px;
	border: 1px solid black;
	border-width: 1px 0;
	text-align: center;
	background: #000;
	background: -webkit-repeating-linear-gradient(top, rgba(0, 0, 0, .9), rgba(48, 48, 48, .7) 2px, rgba(0, 0, 0, .9) 4px) left top / 100% 4px transparent;
	background: repeating-linear-gradient(to bottom, rgba(0, 0, 0, .9), rgba(48, 48, 48, .7) 2px, rgba(0, 0, 0, .9) 4px) left top / 100% 4px transparent;
}

.Touch .lightBox .imageContainer
{
	background-color: {xen:helper unrgba, {xen:property formOverlay.background-color}};
	overflow: hidden;
}

	.lightBox .LbImg
	{
		visibility: hidden;
		position: absolute;
	}

	.lightBox .imageContainer .imageCount
	{
		position: absolute;
		bottom: 0px;
		right: 0px;
		margin: 5px;
		padding: 2px 5px;
		font-size: 11px;
		background: rgba(0,0,0, 0.15);
		border-radius: 3px;
		font-weight: bold;
	}

	/* -------------- */

	.lightBox .imageNav
	{
		position: absolute;
		top: 0;
		height: 100%;
		width: 50px;
		display: block;
		text-align: center;
		outline-style: none;
	}

		.lightBox .imageNav .ctrl
		{
			position: absolute;
			left: 0;
			top: 50%;

			display: block;
			width: 50px;
			height: 50px;
			padding: 0px;
			margin-top: -25px;

			overflow: hidden;
			text-indent: 9999px;
		}

			.lightBox .imageNav .ctrl:after
			{
				content: '\f137';
				position: absolute;
				top: 1px;
				left: 1px;
				width: 48px;
				height: 48px;
				text-align: center;
				vertical-align: middle;
				font-family: FontAwesome;
				font-size: 48px;
				line-height: 48px;
				text-indent: 0;
				font-style: normal;
				font-weight: normal;
				color: #fff;
				opacity: .7;
				transition: opacity .2s;
				text-shadow: 0 0 5px #000;
				pointer-events: none;
			}

				<xen:if is="{$pageIsRtl}">
				.lightBox .imageNav .ctrl:after
				<xen:else />
				.lightBox .imageNav#LbNext .ctrl:after
				</xen:if>
				{
					content: '\f138';
				}

		.lightBox .imageNav#LbPrev { left: 0; }
		.lightBox .imageNav#LbNext { right: 0; }

		.Touch .lightBox .imageNav:hover .ctrl:after,
		.lightBox .imageNav:hover .ctrl:after
		{
			opacity: 1;
		}

/* -------------- */

.lightBox .nav
{
	clear: both;
	padding: 10px;
	padding-top: 5px;
	font-size: 11px;
}

.lightBox .URL
{
	clear: both;
}

/* -------------- */

<xen:set var="$thumbHeight">65</xen:set>

.lightBox .thumbsContainer
{
	/*background: rgba(0,0,0, 0.25);*/

	/*padding: 4px 5px;
	border-radius: 5px;
	position: relative;*/

	overflow: hidden; zoom: 1;
	position: relative;
	height: {xen:calc '{$thumbHeight} + 2'}px;
	padding: 1px;
}

.Touch .lightBox .thumbsContainer
{
	/*background-color: rgb(0,0,0);*/
}

	.lightBox #LbThumbs
	{
		position: absolute;
		left: 0;
		width: 20000em;
	}

		.lightBox #LbThumbs li
		{
			float: left;
			padding: 1px;
			margin-left: 1px;
		}

		.lightBox #LbThumbs li#LbThumbTemplate
		{
			display: none;
		}

			.lightBox #LbThumbs a 
			{
				display: block;
				width: {$thumbHeight}px;
				height: {$thumbHeight}px;
				overflow: hidden;
				position: relative;
			}

				.lightBox #LbThumbs img
				{
					display: block;
					position: absolute;
					visibility: hidden;
				}

	.lightBox #LbReveal
	{
		display: none;
		border: 1px solid white;
		width: {xen:calc '{$thumbHeight} + 2'}px;
		height: {xen:calc '{$thumbHeight} + 2'}px;
		position: absolute;
		top: 0;
	}

/** Login bar basics **/

#loginBar
{
	{xen:property loginBar}
}

	#loginBar .ctrlWrapper
	{
		margin: 0 10px;
	}

	#loginBar .pageContent
	{
		<xen:if is="{xen:property showLoginInNavigation}">
		padding-top: 0;
		margin-top: -{xen:property loginBar.border-bottom-width};
		<xen:else />
		padding-top: {xen:property loginBarCollapsedHeight};
		</xen:if>
		position: relative;
		_height: 0px;
	}

	#loginBar a
	{
		{xen:property loginBarLink}
	}

	#loginBar form
	{
		{xen:property loginBarForm}
	}

		#loginBar .xenForm .ctrlUnit,		
		#loginBar .xenForm .ctrlUnit > dt label
		{
			margin: 0;
			border: none;
		}

			#loginBar .xenForm .ctrlUnit:before
			{
				display: none;
			}

		#loginBar .xenForm .ctrlUnit > dd
		{
			position: relative;
		}

		#loginBar .xenForm .ctrlUnit.submitUnit
		{
			padding-top: 0;
		}

	#loginBar .lostPassword,
	#loginBar .lostPasswordLogin
	{
		font-size: 13px;
	}

	#loginBar .rememberPassword
	{
		font-size: 13px;
		margin-left: 10px;
	}

	#loginBar .textCtrl
	{
		{xen:property loginBarTextCtrl}
	}

	#loginBar .textCtrl[type=text]
	{
		{xen:property loginBarUsername}
	}

	#loginBar .textCtrl:-webkit-autofill /* http://code.google.com/p/chromium/issues/detail?id=1334#c35 */
	{
		background: {xen:property loginBarTextCtrl.background-color} !important;
		color: {xen:property loginBarTextCtrl.color};
	}

	#loginBar .textCtrl:focus
	{
		{xen:property loginBarTextCtrlFocus}
	}

	#loginBar input.textCtrl.disabled
	{
		{xen:property loginBarTextCtrlDisabled}
	}

	#loginBar .button
	{
		min-width: {xen:property loginButtonWidth};
		*width: {xen:property loginButtonWidth};
		{xen:property loginBarButton}
	}

		#loginBar .button.primary
		{
			{xen:property loginBarButtonPrimary}
		}

		#loginBar .button:hover
		{
			{xen:property loginBarButtonHover}
		}

		#loginBar .button:focus
		{
			{xen:property loginBarButtonFocus}
		}

/** changes when eAuth is present **/

#loginBar form.eAuth
{
	-x-max-width: {xen:calc '500 + {xen:property eAuthButtonWidth} + 20'}px; /* normal width + 170px */
}

	#loginBar form.eAuth .ctrlWrapper
	{
		margin-right: {xen:calc '{xen:property eAuthButtonWidth} + 20'}px;
		box-sizing: border-box;
	}

	#loginBar form.eAuth #eAuthUnit
	{
		position: absolute;
		top: 0px;
		right: 10px;
	}

		#eAuthUnit li
		{
			margin-top: 10px;
			line-height: 0;
		}

/** handle **/

#loginBar #loginBarHandle
{
	<xen:if is="{xen:property showLoginInNavigation}">
	display: none;
	<xen:else />
	{xen:property loginBarHandle}
	</xen:if>
}

	#loginBar #loginBarHandle:hover
	{
		{xen:property loginBarHandleHover}
	}

	#loginBar #loginBarHandle a
	{
		text-decoration: inherit;
	}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveWideWidth})
{
	.Responsive #loginBar form.eAuth .ctrlWrapper
	{
		margin-right: 10px;
	}

	.Responsive #loginBar form.eAuth #eAuthUnit
	{
		position: static;
		width: {xen:property eAuthButtonWidth};
		margin: 0 auto 10px;
	}
}
</xen:if>

