.container {
	display: table;
	table-layout: fixed;
	width: 100%;
	zoom: 1;

	{xen:property navSidebarContainer}
}

.navigationSideBar
{
	display: table-cell;
	vertical-align: top;
	*float: left;

	{xen:property navSidebar}
}

	.navigationSideBar .heading
	{
		border-top-left-radius: {xen:property secondaryContent.border-top-left-radius};

		{xen:property navSidebarHeading}
	}

	.navigationSideBar .subHeading
	{
		{xen:property navSidebarSubheading}
	}

	.navigationSideBar .section
	{
		{xen:property navSidebarSection}
	}

	.navigationSideBar .section:first-child
	{
		{xen:property navSidebarSectionFirst}
	}

	.navigationSideBar .section:last-child
	{
		{xen:property navSidebarSectionLast}
	}

	.navigationSideBar .section ul
	{
		{xen:property navSidebarSectionList}
	}

	.navigationSideBar .primaryContent
	{
		{xen:property navSidebarPrimaryContent}
	}

	.navigationSideBar .secondaryContent
	{
		{xen:property navSidebarSecondaryContent}
	}

	.navigationSideBar a
	{
		display: block;
		word-wrap: normal;
		overflow: hidden;
		text-overflow: ellipsis;

		{xen:property navSidebarLink}
	}

		.navigationSideBar li:first-child > a
		{
			{xen:property navSidebarLinkFirst}
		}

		.navigationSideBar li:last-child > a
		{
			{xen:property navSidebarLinkLast}
		}

		.navigationSideBar .section + .section > ul:first-child a:first-child
		{
			{xen:property navSidebarLinkNoHeading}
		}

	.navigationSideBar a:hover,
	.navigationSideBar a:focus
	{
		{xen:property navSidebarLinkHover}
	}

		.navigationSideBar a.primaryContent:hover,
		.navigationSideBar a.primaryContent:focus
		{
			{xen:property navSidebarPrimaryLinkHover}
		}

		.navigationSideBar a.secondaryContent:hover,
		.navigationSideBar a.secondaryContent:focus
		{
			{xen:property navSidebarSecondaryLinkHover}
		}

.mainContentBlock
{
	display: table-cell;
	vertical-align: top;
	margin: 0;
	*margin-left: {xen:property navSidebar.width};
	zoom: 1;
}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveNarrowWidth})
{
	.Responsive .navigationSideBar
	{
		display: block;
		position: relative;
		margin: 0 auto;
		width: 200px;
		box-sizing: border-box;
	}

	.Responsive .navigationSideBar .heading
	{
		margin: 0;
		border-top-right-radius: {xen:property heading.border-top-right-radius};
		border-bottom: 0;
		text-align: center;
		cursor: pointer;

		{xen:property responsiveNavSidebarHeading}
	}

		.Responsive .navigationSideBar .heading span
		{
			{xen:property popupArrowClosed}
		}

	.Responsive .navigationSideBar > ul
	{
		display: none;
		position: absolute;
		background: {xen:property contentBackground};
		border: 1px solid {xen:property primaryLighterStill};
		box-shadow: 5px 5px 25px rgba(0,0,0, 0.5);
		border-top: none;
		width: 200px;
		box-sizing: border-box;
		z-index: 51;
	}

	.Responsive .navigationSideBar > ul.menuVisible
	{
		display: block;
	}

	.Responsive .navigationSideBar .subHeading
	{
		{xen:property responsiveNavSidebarSubheading}
	}

	.Responsive .navigationSideBar .section
	{
		{xen:property responsiveNavSidebarSection}
	}

	.Responsive .navigationSideBar .section:first-child
	{
		{xen:property responsiveNavSidebarSectionFirst}
	}

	.Responsive .navigationSideBar .section:last-child
	{
		{xen:property responsiveNavSidebarSectionLast}
	}

	.Responsive .navigationSideBar .primaryContent
	{
		{xen:property responsiveNavSidebarPrimaryContent}
	}

	.Responsive .navigationSideBar .secondaryContent
	{
		{xen:property responsiveNavSidebarSecondaryContent}
	}

	.Responsive .navigationSideBar a
	{
		{xen:property responsiveNavSidebarLink}
	}

		.Responsive .navigationSideBar li:first-child a
		{
			{xen:property responsiveNavSidebarLinkFirst}
		}

		.Responsive .navigationSideBar li:last-child a
		{
			{xen:property responsiveNavSidebarLinkLast}
		}

		.Responsive .navigationSideBar .section + .section > ul:first-child a:first-child
		{
			{xen:property responsiveNavSidebarLinkNoHeading}
		}

		.Responsive .navigationSideBar a:hover,
		.Responsive .navigationSideBar a:focus
		{
			{xen:property responsiveNavSidebarLinkHover}
		}

			.Responsive .navigationSideBar a.primaryContent:hover,
			.Responsive .navigationSideBar a.primaryContent:focus
			{
				{xen:property responsiveNavSidebarPrimaryLinkHover}
			}

			.Responsive .navigationSideBar a.secondaryContent:hover,
			.Responsive .navigationSideBar a.secondaryContent:focus
			{
				{xen:property responsiveNavSidebarSecondaryLinkHover}
			}

	html.Responsive:not(.hasJs) .navigationSideBar:hover > ul
	{
		display: block;
	}

	.Responsive .mainContentBlock
	{
		display: block;
	}
}
</xen:if>

/* Font Awesome entries */
.bx-wrapper .bx-prev:after,
.bx-wrapper .bx-next:after,
.bx-wrapper .bx-controls-auto .bx-start:after,
.bx-wrapper .bx-controls-auto .bx-stop:after
{
	position: absolute;
	left: 0;
	right: 0;
	top: 0;
	line-height: 1em;
	text-indent: 0;
	font-family: FontAwesome;
	font-weight: normal;
	font-style: normal;
	color: #fff;
	pointer-events: none;
	transition: opacity .2s ease;
	text-shadow: 1px 1px 2px rgba(0, 0, 0, .8);
}

/**
 * BxSlider v4.0 - Fully loaded, responsive content slider
 * http://bxslider.com
 *
 * Written by: Steven Wanderski, 2012
 * http://stevenwanderski.com
 * (while drinking Belgian ales and listening to jazz)
 *
 * CEO and founder of bxCreative, LTD
 * http://bxcreative.com
 */


.scSlider .bx-wrapper 
{
	position: relative;
	margin: 10px auto 30px;
	padding: 0;
	*zoom: 1;
}

.scSlider .bx-wrapper img 
{
	width: auto;
	display: block;
}

.scSlider .bx-wrapper .bx-loading 
{
	min-height: 50px;
	background: url({xen:property imagePath}/nflj/showcase/bxslider/bx_loader.gif) center center no-repeat {xen:property textCtrlBackground};
	height: 100%;
	width: 100%;
	position: absolute;
	top: 0;
	left: 0;
	z-index: 2000;
}

.scSlider .bx-wrapper .bx-viewport 
{
	border: solid transparent 5px;
	left: -5px;
	background: transparent;
}

.showcaseGallerySidebar .scSlider .bx-wrapper .bx-viewport 
{
	border: solid transparent 0px;
	left: 3px;
	background: transparent;
}

.scSlider .bx-wrapper .bx-pager 
{
	text-align: center;
	font-size: .85em;
	font-family: Arial;
	font-weight: bold;
	color: #666;
	padding-top: 20px;
}

.scSlider .bx-wrapper .bx-pager,
.scSlider .bx-wrapper .bx-controls-auto 
{
	position: absolute;
	bottom: -30px;
	width: 100%;
}

.scSlider .bx-wrapper .bx-pager .bx-pager-item,
.scSlider .bx-wrapper .bx-controls-auto .bx-controls-auto-item {

	display: inline-block;
	*zoom: 1;
	*display: inline;
}

.scSlider .bx-wrapper .bx-pager.bx-default-pager a 
{
	background: #666;
	text-indent: -9999px;
	display: block;
	width: 10px;
	height: 10px;
	margin: 0 5px;
	outline: 0;
	-moz-border-radius: 5px;
	-webkit-border-radius: 5px;
	border-radius: 5px;
}

.scSlider .bx-wrapper .bx-pager.bx-default-pager a:hover,
.scSlider .bx-wrapper .bx-pager.bx-default-pager a.active 
{
	background: #000;
}

/* DIRECTION CONTROLS (NEXT / PREV) */

.scSlider .bx-wrapper .bx-controls-direction a 
{
	position: absolute;
	top: 50%;
	margin-top: -16px;
	outline: 0;
	width: 32px;
	height: 32px;
	text-indent: -9999px;
	z-index: 50;
	opacity: 0;
	transition: opacity .25s ease-in-out;
	-moz-transition: opacity .25s ease-in-out;
	-webkit-transition: opacity .25s ease-in-out;
}

.scSlider .bx-wrapper:hover .bx-controls-direction a,
.Touch .scSlider .bx-wrapper .bx-controls-direction a
{
	opacity: 1;
}

.showcaseGallerySidebar .scSlider .bx-wrapper:hover .bx-controls-direction a,
.Touch .showcaseGallerySidebar .scSlider .bx-wrapper .bx-controls-direction a
{
	opacity: 0.7;
}

.scSlider .bx-wrapper .bx-controls-direction a.disabled 
{
	display: none;
}

.scSlider .bx-wrapper .bx-prev 
{
	left: 10px;
}


.showcaseGallerySidebar .scSlider .bx-wrapper .bx-prev 
{
	left: 0px;
}

	.scSlider .bx-wrapper .bx-prev:after,
	.showcaseGallerySidebar .scSlider .bx-wrapper .bx-prev:after
	{
		height: 32px;
		font-size: 30px;
		content: '\f0a8';
		opacity: .75;
	}

.scSlider .bx-wrapper .bx-next 
{
	right: 10px;
}

.showcaseGallerySidebar .scSlider .bx-wrapper .bx-next 
{
	right: 0px;
}

	.scSlider .bx-wrapper .bx-next:after,
	.showcaseGallerySidebar .scSlider .bx-wrapper .bx-next:after
	{
		height: 32px;
		font-size: 30px;
		content: '\f0a9';
		opacity: .75;
	}

.scSlider .bx-wrapper .bx-prev:hover:after
{
	opacity: 1 !important;
}

.bx-wrapper .bx-next:hover:after
{
	opacity: 1 !important;
}





/* AUTO CONTROLS (START / STOP) */

.scSlider .bx-wrapper .bx-controls-auto 
{
	text-align: center;
}

.scSlider .bx-wrapper .bx-controls-auto .bx-start 
{
	display: block;
	text-indent: -9999px;
	width: 10px;
	height: 11px;
	outline: 0;
	margin: 0 3px;
	position: relative;
}

	.scSlider .bx-wrapper .bx-controls-auto .bx-start:after
	{
		content: '\f0da';
		font-size: 14px;
		top: -1px;
		opacity: .75;
	}

	.scSlider .bx-wrapper .bx-controls-auto .bx-start:hover:after,
	.scSlider .bx-wrapper .bx-controls-auto .bx-start.active:after
	{
		opacity: 1;
	}

.scSlider .bx-wrapper .bx-controls-auto .bx-stop 
{
	display: block;
	text-indent: -9999px;
	width: 9px;
	height: 11px;
	outline: 0;
	margin: 0 3px;
	position: relative;
}

	.scSlider .bx-wrapper .bx-controls-auto .bx-stop:after
	{
		content: '\f04c';
		font-size: 10px;
		opacity: .75;
	}

.scSlider .bx-wrapper .bx-controls-auto .bx-stop:hover:after,
.scSlider .bx-wrapper .bx-controls-auto .bx-stop.active:after
{
	opacity: 1;
}

/* PAGER WITH AUTO-CONTROLS HYBRID LAYOUT */

.scSlider .bx-wrapper .bx-controls.bx-has-controls-auto.bx-has-pager .bx-pager 
{
	text-align: left;
	width: 80%;
}

.scSlider .bx-wrapper .bx-controls.bx-has-controls-auto.bx-has-pager .bx-controls-auto 
{
	right: 0;
	width: 35px;
}

/* IMAGE CAPTIONS */

.scSlider .bx-wrapper .bx-caption 
{
	position: absolute;
	bottom: 0;
	left: 0;
	background: #666\9;
	background: rgba(80, 80, 80, 0.75);
	width: 100%;
}

.scSlider .bx-wrapper .bx-caption span 
{
	color: #fff;
	font-family: Arial;
	display: block;
	font-size: .85em;
	padding: 10px;
}

