.es-carousel-wrapper
{
	padding:10px 27px;
	position:relative;
	margin-bottom:20px;
}

.es-carousel
{
	overflow:hidden;
}

	.es-carousel ul
	{
		display:none;
	}

		.es-carousel ul li
		{
			height:100%;
			float:left;
			display:block;
		}

			.es-carousel ul li a
			{
				display:block;
				border-style:solid;
				border-color: {xen:property blocksInnerBorder};
				opacity:0.8;
				-webkit-touch-callout:none;
				/* option */
				-webkit-transition: all 0.2s ease-in-out;
				-moz-transition: all 0.2s ease-in-out;
				-o-transition: all 0.2s ease-in-out;
				-ms-transition: all 0.2s ease-in-out;
				transition: all 0.2s ease-in-out;
			}

			.es-carousel ul li.selected a
			{
				border-color: {xen:property link.color};
				opacity:1.0;
			}

				.es-carousel ul li a img
				{
					display:block;
					border:none;
					max-height:100%;
					max-width:100%;
				}

.es-nav span
{
	position:absolute;
	top:50%;
	left:8px;
	width:14px;
	height:26px;
	margin-top:-13px;
	text-indent:-9000px;
	cursor:pointer;
	opacity:0.8;
	transition: all .2s ease;
}

	.es-nav span.es-nav-next
	{
		right:8px;
		left:auto;
	}

	.es-nav span:hover
	{
		opacity:1.0;
	}

	.es-nav span:after
	{
		content: '\f053';
		font-family: FontAwesome;
		font-size: 14px;
		position: absolute;
		left: 0;
		right: 0;
		top: 0;
		height: 26px;
		text-align: center;
		line-height: 26px;
		text-indent: 0;
		color: {xen:property primaryMedium};
		color: {xen:property link.color};
	}

		.es-nav span:hover:after
		{
			color: {xen:property secondaryMedium};
			color: {xen:property linkHover.color};
		}

		.es-nav span.es-nav-next:after
		{
			content: '\f054';
		}

/* ---------------------------------------------------------------- */

.rg-image-wrapper
{
	position:relative;
	padding:20px 30px;
	min-height:20px;
}

.rg-image
{
	position:relative;
	text-align:center;
	line-height:0px;
}

	.rg-image img
	{
		max-height:100%;
		max-width:100%;
	}

.rg-image-nav a
{
	position:absolute;
	top:0px;
	left:0px;
	background: {xen:property blocksInnerBackground};
	width:28px;
	height:100%;
	text-indent:-9000px;
	cursor:pointer;
	opacity:0.3;
	outline:none;
	transition: all .2s ease;
}

	.rg-image-nav a.rg-image-nav-next
	{
		right:0px;
		left:auto;
	}

	.rg-image-nav a:hover
	{
		opacity:0.8;
	}

	.rg-image-nav a:after
	{
		content: '\f053';
		font-family: FontAwesome;
		font-size: 22px;
		position: absolute;
		left: 0;
		right: 0;
		top: 50%;
		margin-top: -11px;
		height: 22px;
		text-align: center;
		line-height: 22px;
		text-indent: 0;
	}

		.rg-image-nav a.rg-image-nav-next:after
		{
			content: '\f054';
		}

.rg-caption 
{
	text-align:center;
	margin-top:15px;
	position:relative;
}

	.rg-caption p
	{
		font-size:11px;
		letter-spacing:2px;
		font-family: 'Trebuchet MS', 'Myriad Pro', Arial, sans-serif;
		line-height:16px;
		padding:0 15px;
		text-transform:uppercase;
	}

.rg-view
{
	height:30px;
}

	.rg-view a
	{
		display:block;
		float:right;
		width:16px;
		height:16px;
		margin-right:3px;
		opacity:0.8;
		position: relative;
	}

		.rg-view a.rg-view-selected
		{
			display: none;
		}

		.rg-view a:hover
		{
			opacity:1.0;
		}

		.rg-view a:after
		{
			content: '\f150';
			font-family: FontAwesome;
			position: absolute;
			left: 0;
			right: 0;
			top: 0;
			height: 16px;
			text-align: center;
			line-height: 16px;
			font-size: 14px;
		}

			.rg-view a.rg-view-full:after
			{
				content: '\f151';
			}

.rg-loading
{
	position:absolute;
	left: 0;
	top: 0;
	right: 0;
	bottom: 0;
	<xen:if is="{xen:property fbColorScheme} == 'dark'">
	background: {xen:property blocksBackground} url("{xen:property imagePath}/xenforo/widgets/ajaxload.info_000000_facebook.gif") no-repeat 50% 50%;
	<xen:else />
	background: {xen:property blocksBackground} url("{xen:property imagePath}/xenforo/widgets/ajaxload.info_FFFFFF_facebook.gif") no-repeat 50% 50%;
	</xen:if>
	z-index:100;
	opacity:0.7;
}

.showcaseMain 
{
	overflow-x: hidden; 
	overflow-y: hidden;
}

.showcaseItemContainer 
{
	{xen:property primaryContent}
	float: left;
	margin-bottom: 10px;
	margin-right: 10px;
	padding: 10px;	
}

	.showcaseItemContainer .showcaseItemThumb 
	{
		border: 1px solid {xen:property blocksInnerBorder};
		height: 175px;
		width: 250px;		
		position: relative;
	}

		.showcaseItemThumb .showcaseItemThumbnail 
		{
			height: 175px;		
			width: 250px;
		}

		.showcaseItemThumb span.featured 
		{
			display: none;
		}

			.canTransform .showcaseItemThumb span.featured
			{
				display: block;
				width: 70px;
				height: 70px;
				position: absolute;     
				top:-2px;
				left:-2px;
				overflow: hidden;
				opacity: .7;
				transition: opacity 0.2s ease;
			}

				.canTransform .showcaseItemThumb span.featured:after
				{
					content: 'Featured';
					background: {xen:property secondaryMedium};
					color: {xen:property secondaryLightest};
					font-weight: normal;
					font-style: normal;
					width: 100px;
					font-size: 12px;
					line-height: 18px;
					height: 18px;
					text-align: center;
					position: absolute;
					top: 17px;
					left: -25px;
					pointer-events: none;
					text-shadow: 1px 1px 1px {xen:property secondaryDark};
					-webkit-transform: rotate(-45deg);
					-ms-transform: rotate(-45deg);
					transform: rotate(-45deg);
				}

				.canTransform .showcaseItemContainer:hover span.featured
				{
					opacity: 1;
				}

		.showcaseItemThumb .iconKey span
		{
			{xen:property dicussionListIcon}
		}

			.showcaseItemThumb .iconKey span:after
			{
				{xen:property dicussionListIconAfter}
			}

			.showcaseItemThumb .iconKey .moderated:after { content: '\e271'; font-family: 'Glyphicons Regular', 'Glyphicons'; font-size: 12px; }
			.showcaseItemThumb .iconKey .deleted:after { content: '\f00d'; }


	.showcaseItemContainer .showcaseItemInfo 
	{
		max-width: 200px;
	}

		.showcaseItemInfo .showcaseItemTitle 
		{
			font-size: 14px;
			font-weight: bold;
			height: 35px;
			line-height: 1.2;
			overflow: hidden;
			padding-top: 10px;
		}

		.showcaseItemInfo .showcaseItemRating 
		{
			padding-top: 10px;
			min-height: 25px;			
		}

			.showcaseItemInfo .showcaseItemRating .Hint 
			{
				float: right;
			}

.showcaseItemTooltip 
{
	max-width: 350px;
}

.showcaseNoItems 
