	.itemStateDisplay .iconKey span:after
	{
		{xen:property dicussionListIconAfter}
	}

	.itemStateDisplay .iconKey .moderated:after { content: '\e271'; font-family: 'Glyphicons Regular', 'Glyphicons'; font-size: 12px; }
	.itemStateDisplay .iconKey .deleted:after { content: '\f00d'; }

.thumbnailContainer span.featured 
{
	display: none;
}

	.canTransform .thumbnailContainer span.featured
	{
		display: block;
		width: 70px;
		height: 70px;
		position: absolute;     
		top:-2px;
		left:-2px;
		overflow: hidden;
		opacity: .7;
		transition: opacity 0.2s ease;
	}

		.canTransform .thumbnailContainer span.featured:after
		{
			content: 'Featured';
			background: {xen:property secondaryMedium};
			color: {xen:property secondaryLightest};
			font-weight: normal;
			font-style: normal;
			width: 100px;
			font-size: 12px;
			line-height: 18px;
			height: 18px;
			text-align: center;
			position: absolute;
			top: 17px;
			left: -25px;
			pointer-events: none;
			text-shadow: 1px 1px 1px {xen:property secondaryDark};
			-webkit-transform: rotate(-45deg);
			-ms-transform: rotate(-45deg);
			transform: rotate(-45deg);
		}

		.canTransform .thumbnailContainer:hover span.featured
		{
			opacity: 1;
		}


.thumbnailOverlay
{
	bottom: 0;
	position: absolute;
	z-index: 199;
	visibility: hidden;
	opacity: 0;
	transition: visibility 0s linear 0.5s,opacity 0.5s linear;
	text-shadow: 0px 1px 1px #000;
	min-height: 20%;
}

