<xen:if is="{xen:property enableResponsive}">
	@media (max-width: 1100px)
	{
		.Responsive .detailContainer .statsSection i
		{
			font-size: 105%;
		}

		.gridCol:nth-child({xen:property scGridDefaultPerRow}n+1),
		.showcase_find_new_items .gridSpan:nth-child({xen:calc '{xen:property scGridDefaultPerRow} + 1'}n+1)
		{
			clear: none;
		}

		.Responsive .gridSpan,
		.Responsive .gridCol
		{
			width: {xen:calc '(100 / {xen:property scGridWideWidthPerRow}) - 2'}%;
		}

		.Responsive .gridSpan:nth-child({xen:property scGridWideWidthPerRow}n+1),
		.Responsive .gridCol:nth-child({xen:property scGridWideWidthPerRow}n+1)
		{
			clear: both;
		}
	}

	@media (max-width:{xen:property maxResponsiveWideWidth})
	{
		.Responsive .detailContainer .statsSection i
		{
			font-size: 105%;
		}

		.gridCol:nth-child({xen:property scGridDefaultPerRow}n+1),
		.showcase_find_new_items .gridSpan:nth-child({xen:calc '{xen:property scGridDefaultPerRow} + 1'}n+1)
		{
			clear: none;
		}

		.Responsive .gridSpan,
		.Responsive .gridCol
		{
			width: {xen:calc '(100 / {xen:property scGridWideWidthPerRow}) - 2'}%;
		}

		.Responsive .gridSpan:nth-child({xen:property scGridWideWidthPerRow}n+1),
		.Responsive .gridCol:nth-child({xen:property scGridWideWidthPerRow}n+1)
		{
			clear: both;
		}

		.Responsive .thumbnailOverlay .overlayDetails .infoContainer .secondRow .categoryInfo
		{
			display: block;
			width: 100%;
		}

		.Responsive .thumbnailOverlay .overlayDetails .infoContainer .secondRow .ratingInfo
		{
			display: block;
			width: 100%;
		}
	}

	@media (max-width:{xen:property maxResponsiveMediumWidth})
	{
		.Responsive .gridSpan:nth-child({xen:property scGridWideWidthPerRow}n+1),
		.Responsive .gridCol:nth-child({xen:property scGridWideWidthPerRow}n+1)
		{
			clear: none;
		}

		.Responsive .gridSpan,
		.Responsive .gridCol
		{
			width: {xen:calc '(100 / {xen:property scGridMediumWidthPerRow}) - 2'}%;
		}

		.Responsive .gridSpan:nth-child({xen:property scGridMediumWidthPerRow}n+1),
		.Responsive .gridCol:nth-child({xen:property scGridMediumWidthPerRow}n+1)
		{
			clear: both;
		}

		.Responsive .detailContainer .statsSection i
		{
			font-size: 100%;
		}
	}

	@media (max-width:{xen:property maxResponsiveNarrowWidth})
	{
		.Responsive .detailContainer .statsSection div
		{
			display: inline-block;
			width: 45%;
		}

		.Responsive .AttachedImage .mediaLabels .mediaLabel
		{
			font-size: 16px;
		}

		.Responsive .mediaLabels .mediaLabel
		{
			font-size: 9px;
		}

		.Responsive #InlineModOverlay
		{
			margin-left: 30px;
		}

		.Responsive .showcaseItemTooltip 
		{
			max-width: 300px;
		}
	}

	@media (max-width:340px)
	{
		.Responsive .gridGroup
		{
			margin-left: 1%;
			margin-right: 1%;
		}

		.Responsive .gridSpan:nth-child({xen:property scGridMediumWidthPerRow}n+1),
		.Responsive .gridCol:nth-child({xen:property scGridMediumWidthPerRow}n+1)
		{
			clear: both;
		}

		.Responsive .gridSpan,
		.Responsive .gridCol
		{
			width: {xen:calc '(100 / {xen:property scGridNarrowWidthPerRow}) - 2'}%;
		}

		.Responsive .gridSpan:nth-child({xen:property scGridNarrowWidthPerRow}n+1),
		.Responsive .gridCol:nth-child({xen:property scGridNarrowWidthPerRow}n+1)
		{
			clear: both;
		}

		.Responsive .showcaseItemTooltip 
		{
			max-width: 300px;
		}
	}
</xen:if>

