.subHeading + .nodeList
{
	margin-top: 10px;
	margin-bottom: 10px;
}

	.watch_forums .subHeading
	{
		display: none;
	}

.nodeList { zoom: 1; }
.nodeList .node {
	zoom: 1;
	vertical-align: bottom;
}

.nodeList .node.level_1
{
	margin-bottom: 15px;
}

.nodeList .node.level_1:last-child
{
	margin-bottom: 0;
}

.nodeList .node.groupNoChildren + .node.groupNoChildren
{
	margin-top: -{xen:calc '15 - {xen:property nodeContent.margin-top}'}px;
}

.node .nodeInfo,
.node .nodeInfoInner
{
	overflow: hidden; zoom: 1;
	position: relative;
	min-height: {xen:calc '{xen:property nodeIcon.height} + 20'}px;
}

	.node .nodeInfo.primaryContent,
	.node .nodeInfo.secondaryContent
	{
		padding: 0;
	}

.node .nodeIcon
{
	{xen:property nodeIcon}	
}

	.node .forumNodeInfo .nodeIcon,
	.node .categoryForumNodeInfo .nodeIcon
	{
		{xen:property nodeIconForum}

		<xen:if is="{$pageIsRtl}">
		{xen:property nodeIconForumRTL}
		</xen:if>
	}

		<xen:if is="{xen:property nodeIconHD}">
		@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi), (min-resolution: 1.5dppx)
		{
			.node .forumNodeInfo .nodeIcon,
			.node .categoryForumNodeInfo .nodeIcon
			{
				{xen:property nodeIconForumHD}

				<xen:if is="{$pageIsRtl}">
				{xen:property nodeIconForumRTLHD}
				</xen:if>
			}
		}
		</xen:if>

	<xen:set var="$prefix"><xen:if is="{xen:property loggedInOnlyUnreadNodeIcons}">.LoggedIn </xen:if></xen:set>
	{$prefix} .node .forumNodeInfo.unread .nodeIcon,
	{$prefix} .node .categoryForumNodeInfo.unread .nodeIcon
	{
		{xen:property nodeIconForumUnread}

		<xen:if is="{$pageIsRtl}">
		{xen:property nodeIconForumUnreadRTL}
		</xen:if>
	}

		<xen:if is="{xen:property nodeIconHD}">
		@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi), (min-resolution: 1.5dppx)
		{
			{$prefix} .node .forumNodeInfo.unread .nodeIcon,
			{$prefix} .node .categoryForumNodeInfo.unread .nodeIcon
			{
				{xen:property nodeIconForumUnreadHD}

				<xen:if is="{$pageIsRtl}">
				{xen:property nodeIconForumUnreadRTLHD}
				</xen:if>
			}
		}
		</xen:if>

	.node .pageNodeInfo .nodeIcon
	{
		{xen:property nodeIconPage}

		<xen:if is="{$pageIsRtl}">
		{xen:property nodeIconPageRTL}
		</xen:if>
	}

		<xen:if is="{xen:property nodeIconHD}">
		@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi), (min-resolution: 1.5dppx)
		{
			.node .pageNodeInfo .nodeIcon
			{
				{xen:property nodeIconPageHD}

				<xen:if is="{$pageIsRtl}">
				{xen:property nodeIconPageRTLHD}
				</xen:if>			
			}
		}
		</xen:if>

	.node .linkNodeInfo .nodeIcon
	{
		{xen:property nodeIconLink}

		<xen:if is="{$pageIsRtl}">
		{xen:property nodeIconLinkRTL}
		</xen:if>
	}

		<xen:if is="{xen:property nodeIconHD}">
		@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi), (min-resolution: 1.5dppx)
		{
			.node .linkNodeInfo .nodeIcon
			{
				{xen:property nodeIconLinkHD}

				<xen:if is="{$pageIsRtl}">
				{xen:property nodeIconLinkRTLHD}
				</xen:if>
			}
		}
		</xen:if>

.node .nodeIcon i
{
	{xen:property nodeIconGlyph}
}

	.node .nodeIcon i:before
	{
		font-size: inherit;
		margin: 0;
		color: inherit;
	}

.node .nodeText
{
	{xen:property nodeText}
}

	.node .nodeText .nodeTitle,
	.node .nodeText .nodeTitle a
	{	
		{xen:property nodeTitle}
	}

		.LoggedIn .node .unread .nodeText .nodeTitle,
		.LoggedIn .node .unread .nodeText .nodeTitle a
		{
			{xen:property nodeTitleUnread}
		}

		.node .nodeText .nodeTitle a:hover,
		.LoggedIn .node .unread .nodeText .nodeTitle a:hover
		{
			{xen:property nodeTitleHover}
		}

	.node .nodeDescription
	{
		{xen:property nodeDescription}
	}

	.hasJs .node .nodeDescriptionTooltip
	{
		/* will be shown as a tooltip */
		display: none;
	}

	.Touch .node .nodeDescriptionTooltip
	{
		/* touch browsers don't see description tooltips */
		display: block;
	}

	.node .nodeStats
	{
		{xen:property nodeStats}
	}

		.node .nodeInfoInner .nodeStats
		{
			overflow: visible;
		}

	.node .nodeExtraNote
	{
		text-align: right;
		font-size: 11px;
		color: {xen:property mutedTextColor};
	}

	.node .subForumList
	{
		overflow: hidden; *zoom: 1;
		margin-bottom: {xen:property nodeText.margin-bottom};
		margin-left: {xen:calc '{xen:property nodeText.margin-left} - 5'}px;
		{xen:property nodeSubforumsContainer}
	}

		.node .subForumList.outside
		{
			{xen:property nodeSubforumsContainerOutside}

			margin-left: 0;
		}

		.node .subForumList li
		{
			float: left;
		}

		.node .subForumList li .nodeTitle
		{
			{xen:property nodeSubforumsItem}
		}

			.node .subForumList.outside li .nodeTitle
			{
				margin-left: 0;
				box-sizing: border-box;

				{xen:property nodeSubforumsItemOutside}
			}

			.node .subForumList.outside .unread .nodeTitle,
			.node .subForumList .unread .nodeTitle
			{
				{xen:property nodeSubforumsItemUnread}
			}

			.node .subForumList.outside li .nodeTitle:hover,
			.node .subForumList li .nodeTitle:hover
			{
				{xen:property nodeSubforumsItemHover}
			}

			.node .subForumList li .nodeTitle a
			{
				{xen:property nodeSubforumsItemTitle}
			}

			.node .subForumList .unread .nodeTitle a
			{
				{xen:property nodeSubforumsItemTitleUnread}
			}

			.node .subForumList li .nodeTitle:hover a
			{
				{xen:property nodeSubforumsItemTitleHover}
			}

			.node .subForumList li ol,
			.node .subForumList li ul
			{
				display: none;
			}

.node .nodeLastPost
{
	{xen:property secondaryContent}

	{xen:property nodeLastPost}
	margin-right: 0;
	right: {xen:calc '{xen:property nodeLastPost.margin-right} + {xen:property nodeLastPost.margin-left}'}px;
}

.node .nodeLastPost .lastThreadTitle
{
	text-overflow: ellipsis;
	max-width: 100%;
	display: block;
	overflow: hidden;
}

	.node .nodeLastPost .lastThreadMeta
	{
		display: block;
	}

	.node .nodeLastPost .noMessages
	{
		line-height: 28px;
	}

.node .nodeControls
{
	position: absolute;
	right: {xen:calc '{xen:property nodeLastPost.border-left-width} + {xen:property nodeLastPost.padding-left} + {xen:property nodeLastPost.width} + {xen:property nodeLastPost.padding-right} + {xen:property nodeLastPost.border-right-width} + {xen:property nodeLastPost.margin-right}'}px;
	{xen:property nodeControls}
}

	.node .tinyIcon
	{
		{xen:property nodeTinyIcon}
	}

	.node .nodeInfo:hover .tinyIcon[href],
	.Touch .node .tinyIcon
	{
		{xen:property nodeTinyIconHover}
	}

		.node .feedIcon
		{
			background: transparent;
			position: relative;
			opacity: 1;
			width: 16px;
			height: 16px;
		}

		.node .feedIcon:after
		{
			{xen:property tinyIconRSS}

			<xen:if is="{$pageIsRtl}">
			-ms-transform: scale(-1, 1);
			-webkit-transform: scale(-1, 1);
			transform: scale(-1, 1);
			</xen:if>
		}

			.Touch .node .feedIcon:after
			{
				opacity: 1;
			}

		.node .feedIcon:hover:after,
		.node .nodeInfo:hover .feedIcon:after
		{
			{xen:property tinyIconRSSHover}
		}

/* description tooltip */

.nodeDescriptionTip
{
	{xen:property nodeDescriptionTip}
}

	.nodeDescriptionTip .arrow
	{
		{xen:property nodeDescriptionTipArrow}
	}

	.nodeDescriptionTip.arrowBottom .arrow
	{
		top: auto;
		left: 10px;
		bottom: -6px;
		border: 6px solid transparent;
		border-top-color: {xen:property tooltip.background-color};
		border-bottom: 1px none black;
	}

