{
	{xen:property categoryBlock}
}

	.nodeList .category.level_1.collapsed
	{
		{xen:property categoryBlockCollapsed}
	}

/* category strip - used for L1 categories and group headers */

.nodeList .categoryStrip
{
	{xen:property subHeading}

	<xen:if is="{$pageIsRtl}">
	{xen:property subHeadingRTL}
	</xen:if>

	{xen:property categoryStrip}

	<xen:if is="{$pageIsRtl}">
	{xen:property categoryStripRTL}
	</xen:if>
}

	.nodeList .category.collapsed .categoryStrip
	{
		{xen:property categoryStripCollapsed}
	}

		.nodeList > li.category.collapsed:last-child .categoryStrip
		{
			margin-bottom: 0;
		}


	.nodeList .categoryStrip:hover,
	.nodeList .category.collapsed .categoryStrip:hover
	{
		{xen:property categoryStripHover}
	}

	.nodeList .categoryStrip.empty
	{
		{xen:property categoryStripEmpty}

		<xen:if is="{xen:property hideEmptyCategoryTitles}">
		display: none;
		</xen:if>
	}

	<xen:if is="{xen:property floatingCategoryDescription}">
	.nodeList .categoryStrip
	{
		overflow: hidden;
	}

	.nodeList .categoryStrip .nodeTitle
	{
		float: left;
	}

	.nodeList .categoryStrip .nodeDescription
	{
		float: right;
		padding-top: 4px;
		text-align: right;
	}
	</xen:if>

	.nodeList .categoryStrip .nodeTitle
	{
		{xen:property categoryStripTitle}
	}

		.nodeList .categoryStrip .nodeTitle a,
		.nodeList .categoryStrip .nodeTitle i
		{
			color: {xen:property categoryStripTitle.color};
		}

			.nodeList .categoryStrip .nodeTitle a.has-category-glyph
			{
				margin-left: 5px;
			}

	.nodeList .categoryStrip .nodeDescription
	{
		{xen:property categoryStripDescription}
	}

		.nodeList .categoryStrip .nodeDescription a
		{
			color: {xen:property categoryStripDescription.color};
		}

.nodeList .node.groupNoChildren + .node.groupNoChildren .categoryStrip
{
	display: none;
}

/* node collapse button */
.categoryStrip .categoryToggle
{
	text-decoration: none !important;
	outline-style: none !important;
	{xen:property categoryToggle}
}

	.categoryStrip .categoryToggle:after
	{
		content: '\e192';
		font-family: 'Glyphicons Regular', 'Glyphicons';
	}

	.categoryStrip .categoryToggle.collapsed:after
	{
		content: '\e191';
	}

	.categoryStrip .categoryToggle:hover
	{
		color: {xen:property categoryStripTitle.color};

		{xen:property categoryToggleHover}
	}


/* node stats area */

.nodeStats
{
	overflow: hidden; zoom: 1;
}

.nodeStats dl,
.subForumsPopup
{
	float: left;
	display: block;
	margin-right: 3px;
}

.subForumsPopup.Popup .PopupControl.PopupOpen
{
	background-image: none;
}

.subForumsPopup a.PopupControl
{
	padding-left: 5px;
	padding-right: 5px;
}

.subForumsPopup .dt
{
	color: {xen:property mutedTextColor};
}

.subForumsPopup .PopupOpen .dt
{
	color: {xen:property body.color};
}

.subForumsMenu .node .node /* for depths 2+ */
{
	padding-left: 10px;
}

	.subForumsMenu .node .nodeTitle,
	.subForumsMenu .node .nodeTitle a
	{
		font-size: 11px;
	}

	.LoggedIn .subForumsMenu .node .unread .nodeTitle,
	.LoggedIn .subForumsMenu .node .unread .nodeTitle a
	{
		{xen:property nodeTitleUnread}
	}

	.subForumsMenu .node .nodeTitle a:hover
	{
		{xen:property nodeTitleHover}
	}

/** new discussion button below nodelist **/

.nodeListNewDiscussionButton
{
	margin-top: 10px;
	text-align: right;
}

/** compact nodes list */
.node.compact .nodeList:after
{
	content: '';
	display: block;
	clear: both;
}

.node.compact .node.compact-node
{
	float: left;
	width: 50%;
	-moz-box-sizing: border-box;
	box-sizing: border-box;
}

.node.compact .node.firstColumn
{
	clear: left;
}

.node.compact .node.compact-node .nodeControls
{
	right: 5px;
}

.node.compact .node.compact-node .nodeText
{
	margin-right: 30px;
	overflow: hidden;
}

.node.compact-node .nodeLastPost .noMessages
{
	display: none;
}

<xen:if is="{xen:property compactNodeListLastPost}">
.node.compact .node.compact-node .nodeText
{
	margin-bottom: 0;
}

.node.compact .node.compact-node .nodeLastPost
{
	margin: 3px 30px 5px {xen:property nodeText.margin-left};
	position: relative;
	top: 0;
	right: 0;
	width: auto;
	height: auto;
	overflow: hidden;
	@property "nodeLastPostCompact";
	padding: 0;
	border-width: 0;
	background: transparent;
	@/property "/nodeLastPostCompact";
}
.node.compact .node.compact-node .nodeLastPost .lastThreadTitle,
.node.compact .node.compact-node .nodeLastPost .lastThreadMeta
{
	float: left;
	max-width: 45%;
	margin: 0;
	padding: 0;
}
.node.compact .node.compact-node .nodeLastPost .lastThreadMeta:before
{
	content: '|';
	margin: 0 0 0 3px;
	opacity: .5;
}
<xen:else />
.node.compact .node.compact-node .nodeLastPost
{
	display: none;
}
</xen:if>

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveMediumWidth})
{
	.Responsive .node .nodeText
	{
		margin-right: 0;
	}

	.Responsive.Touch .node .nodeDescriptionTooltip,
	.Responsive .node .nodeDescription
	{
		display: none;
	}

	<xen:if is="{xen:property responsiveNodeLastPost}">
	.Responsive .node .nodeText
	{
		margin-bottom: 0;
		overflow: hidden;
	}

	.Responsive .node .nodeLastPost
	{
		margin: 3px 30px 5px {xen:property nodeText.margin-left};
		position: relative;
		top: 0;
		right: 0;
		width: auto;
		height: auto;
		overflow: hidden;
		clear: both;

		@property "nodeLastPostCompact";
		padding: 0;
		border-width: 0;
		background: transparent;
		@/property "/nodeLastPostCompact";
	}

	.Responsive .node .nodeLastPost .lastThreadTitle,
	.Responsive .node .nodeLastPost .lastThreadMeta
	{
		float: left;
		max-width: 45%;
		margin: 0;
		padding: 0;
	}

	.Responsive .node .nodeLastPost .lastThreadMeta:before
	{
		content: '|';
		margin: 0 0 0 3px;
		opacity: .5;
	}
	<xen:else />
	.Responsive .node .nodeLastPost
	{
		position: static;
		height: auto;
		width: auto;
		background: none;
		border: none;
		padding: 0;
		margin: -{xen:calc '{xen:property nodeText.margin-bottom} - 2'}px 0 {xen:property nodeText.margin-bottom} {xen:property nodeText.margin-left};
	}

		.Responsive .node .nodeLastPost .noMessages 
		{
			display: none;
		}

		.Responsive .node .nodeLastPost .lastThreadTitle,
		.Responsive .node .nodeLastPost .lastThreadUser
		{
			display: none;
		}

		.Responsive .node .nodeLastPost .lastThreadDate:before
		{
			content: attr(data-latest);
		}
	</xen:if>

	.Responsive .node .nodeControls
	{
		display: none;
	}

	.Responsive .node .subForumList
	{
		display: none;
	}

	.Responsive .nodeDescriptionTip
	{
		width: auto;
		max-width: 350px;
	}
}

@media (max-width:{xen:property maxResponsiveNarrowWidth})
{
	.Responsive .subForumsPopup
	{
		display: none;
	}
}
</xen:if>

.PageNav
{
	{xen:property pageNav}
}

	.PageNav .hidden
	{
		display: none;
	}

	.PageNav .pageNavHeader,
	.PageNav a,
	.PageNav .scrollable
	{
		display: block;
		float: left;
		margin-right: {xen:property pageNavLinkSpacing};
	}

	.PageNav .pageNavHeader
	{
		padding: 1px 3px 1px 0;
	}

	.PageNav a
	{		
		{xen:property pageNavItem}


		width: {xen:property pageNavLinkWidth};
	}

	/*
		@property "pageNavPage";

		@property "/pageNavPage";
		*/

		.PageNav a[rel=start]
		{
			width: {xen:property pageNavLinkWidth} !important;
		}

		.PageNav a.text
		{
			width: auto !important;
			padding: 0 4px;
		}

		.PageNav a
		{
		}

		.PageNav a.currentPage
		{
			{xen:property pageNavCurrentPage}
		}

		a.PageNavPrev,
		a.PageNavNext
		{
			{xen:property pageNavScroller}

			width: {xen:property pageNavLinkWidth} !important;
		}

		.PageNav a:hover,
		.PageNav a:focus
		{
			{xen:property pageNavPageHover}
		}

	.PageNav a.distinct
	{
		margin-left: {xen:property pageNavLinkSpacing};
	}

	.PageNav .scrollable
	{
		position: relative;
		overflow: hidden;
		width: {xen:calc '({xen:property pageNavLinkWidth} * 5) + ({xen:property pageNavLinkSpacing} * 4) + ({xen:property pageNavItem.border-width} * 10)'}px; /* width of 5 page numbers plus their margin & border */
		height: 18px; /* only needs to be approximate */
	}

		.PageNav .scrollable .items
		{
			display: block;
			width: 20000em; /* contains scrolling items, should be huge */
			position: absolute;
			display: block;
		}

/** Edge cases - large numbers of digits **/

.PageNav .gt999 
{
	font-size: 9px;
	letter-spacing: -0.05em; 
}

.PageNav.pn5 a { width: {xen:calc '5 * 4 + 9'}px; } .PageNav.pn5 .scrollable { width: {xen:calc '(5 * 4 + 9) * 5 + ({xen:property pageNavLinkSpacing} * 4) + ({xen:property pageNavItem.border-width} * 10)'}px; }
.PageNav.pn6 a { width: {xen:calc '6 * 4 + 9'}px; } .PageNav.pn6 .scrollable { width: {xen:calc '(6 * 4 + 9) * 5 + ({xen:property pageNavLinkSpacing} * 4) + ({xen:property pageNavItem.border-width} * 10)'}px; }
.PageNav.pn7 a { width: {xen:calc '7 * 4 + 9'}px; } .PageNav.pn7 .scrollable { width: {xen:calc '(7 * 4 + 9) * 5 + ({xen:property pageNavLinkSpacing} * 4) + ({xen:property pageNavItem.border-width} * 10)'}px; }

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveMediumWidth})
{
	.Responsive .PageNav .pageNavHeader
	{
		display: none;
	}
}

@media (max-width:{xen:property maxResponsiveNarrowWidth})
{
	.Responsive .PageNav .unreadLink
	{
		display: none;
	}
}
</xen:if>

