}

.pollBlock .questionMark
{
	{xen:property pollQuestionMark}
}

.pollBlock .pollNotes
{
	font-size: 11px;
}

.pollBlock .question
{
	overflow: hidden; zoom: 1;
}

	.pollBlock .question .questionText
	{
		{xen:property pollQuestionText}
	}

	.pollBlock .question .editLink
	{
		font-size: 11px;
		float: right;
	}

	.pollBlock .question .closeDate
	{
		clear: both;
		font-size: 11px;
	}

.pollBlock .pollOptions,
.pollBlock .pollResults
{
	width: 100%;
	table-layout: fixed;
	display: table;
	margin: 5px 0;
	padding: 0;
	border-top: 1px solid {xen:property innerBottomBorder};
	border-bottom: 1px solid {xen:property innerTopBorder};
}

	.pollBlock .pollOption label
	{
		{xen:property pollOptionLabel}
	}

	.pollBlock .pollOption label:hover
	{
		{xen:property pollOptionLabelHover}
	}

.pollBlock .buttons
{
	text-align: right;
	line-height: 27px;
	display: table;
	width: 100%;
}

.pollBlock .buttons .button
{
	min-width: 120px;
	_width: 120px;
}

	.pollBlock .buttons .pollNotes
	{
		float: left;
		text-align: left;
		line-height: 1.28;
		margin-right: 5px;
		margin-top: 5px;
	}

.pollBlock .pollResult
{
	display: table-row;
}

	.pollBlock .pollResult,
	.pollBlock .pollOption
	{
		position: relative;
	}

	.pollBlock .pollResult:before,
	.pollBlock .pollOption:before
	{
		content: '';
		display: block;
		position: absolute;
		top: 0;
		left: 0;
		right: 0;
		border-top: 1px solid {xen:property innerTopBorder};
	}

	.pollBlock .pollResult:after,
	.pollBlock .pollOption:after
	{
		content: '';
		display: block;
		position: absolute;
		bottom: 0;
		left: 0;
		right: 0;
		border-bottom: 1px solid {xen:property innerBottomBorder};
	}

.pollBlock .pollResult div,
.pollBlock .pollResult h3
{
	display: table-cell;
	padding: 5px 0;
}

	.pollBlock .votedIconCell
	{
		width: 15px;
		text-align: center;
		vertical-align: top;
	}

	.pollBlock .optionText,
	.pollBlock .questionText
	{
		max-width: 100%;
	}

	.pollBlock .voted .optionText,
	.pollBlock .voted .votedIconCell
	{
		font-weight: bold;
	}

	.pollBlock .pollResult .barCell
	{
		width: 100px;
		padding: 0 0 0 10px;
	}

		.pollResult .barContainer
		{
			display: inline-block;
			zoom: 1;
			vertical-align: middle;
			box-sizing: border-box;
			{xen:property pollResultBarContainer}
			<xen:if is="{xen:property pollResultBarOpacity} != '1'">
			background-color: {xen:helper rgba, {xen:property pollResultBarContainer.background-color}, {xen:property pollResultBarOpacity}};
			</xen:if>
		}

			.pollResult .barContainer.empty
			{
				{xen:property pollResultBarContainerEmpty}
			}

			.pollResult .bar
			{
				display: block;
				zoom: 1;
				{xen:property pollResultBar}
			}

	.pollBlock .pollResult .count,
	.pollBlock .pollResult .percentage
	{
		word-wrap: break-word;
		text-align: right;
		padding-left: 10px;
	}

	.pollBlock .pollResult .count
	{
		width: 80px;
	}

	.pollBlock .pollResult .percentage
	{
		width: 50px;
	}

.xenOverlay > .PollContainer > .section,
.xenOverlay > .PollContainer > .sectionMain
{
	background: none;
	margin: 0;
}

.overlayScroll.pollResultsOverlay 
{
	padding-right: 10px;
}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveNarrowWidth})
{
	.Responsive .pollBlock .pollResult .optionText
	{
		border-top: solid 1px {xen:property primaryLighterStill};
	}

	.Responsive .pollBlock .pollResult:first-child .optionText
	{
		border-top: none;
	}

	.Responsive .pollBlock .pollResult .optionText
	{
		display: block;
	}

	.Responsive .pollBlock .pollResult .barCell
	{
		padding: 0;
	}

	.Responsive .pollBlock .pollResult .barCell,
	.Responsive .pollBlock .pollResult .count,
	.Responsive .pollBlock .pollResult .percentage
	{
		display: inline-block;
		font-size: 11px;
	}
}
</xen:if>

