.rating
{
	line-height: 18px;
}

	.rating .star
	{
		width: 18px;
		height: 18px;
		display: inline-block;

		border: none;
		outline: none;
		padding: 0;
		background: transparent;

		text-indent: 9999em;
		overflow: hidden;
		white-space: nowrap;

		vertical-align: bottom;
		position: relative;
	}

		.rating .star:after
		{
			content: '\f006';
			font-family: 'FontAwesome';
			display: block;
			position: absolute;
			left: 0;
			right: 0;
			top: 0;
			bottom: 0;
			text-align: center;
			vertical-align: middle;
			font-size: 17px;
			line-height: 17px;
			color: {xen:property link.color};
			font-weight: normal;
			font-style: normal;
			text-indent: 0;
			pointer-events: none;
		}

			.rating .star:hover:after
			{
				color: {xen:property linkHover.color};
			}

			.ratings:hover > .star:after
			{
				color: {xen:property linkHover.color};
			}

				.ratings:hover > .star:hover + .star:after,
				.ratings:hover > .star:hover + .star + .star:after,
				.ratings:hover > .star:hover + .star + .star + .star:after,
				.ratings:hover > .star:hover + .star + .star + .star + .star:after,
				.ratings:hover > .star:hover + .star + .star + .star + .star + .star:after,
				.ratings:hover > .star:hover + .star + .star + .star + .star + .star + .star:after
				{
					color: {xen:property link.color};
				}

	.rating button.star
	{
		cursor: pointer;
	}

		.rating .star.Full:after
		{
			content: '\f005';
		}

		.rating .star.Half:after,
		.rating .star.Full.Half:after
		{
			content: '\f123';
		}

	.rating .RatingValue
	{
		display: none;
	}

