			.resourceAlerts .deletedAlert .icon:after { content: '\f00d'; }
			.resourceAlerts .moderatedAlert .icon:after { content: '\e271'; font-family: 'Glyphicons Regular', 'Glyphicons'; font-size: 12px; }

<xen:if is="{xen:property enableResponsive}">
