#searchBar
{
	position: relative;
	zoom: 1;
	z-index: 52; /* higher than breadcrumb arrows */
}

	<xen:set var="$searchBarOutsideWrapper">0</xen:set>
	<xen:if is="{xen:property enableAlternativeHeader} && {xen:property globalWrapper}">
		<xen:if is="{xen:property enableAlternativeNavigation} || !{xen:property quickSearchInHeader}">
			<xen:if is="!{xen:property globalWrapperHeader} && !({xen:property globalWrapperNavigation} || {xen:property enableAlternativeNavigation})">
				<xen:set var="$searchBarOutsideWrapper">1</xen:set>
			</xen:if>
		<xen:elseif is="!{xen:property globalWrapperHeader}" />
			<xen:set var="$searchBarOutsideWrapper">1</xen:set>
		</xen:if>
	</xen:if>

	#logoBlock #searchBar
	{
		{xen:property searchBarInHeader}
	}

	#QuickSearchPlaceholder
	{
		top: {xen:calc '-1 * ({xen:property headerTabHeight} / 2 + 16 / 2)'}px;
		{xen:property searchBarPlaceholder}
	}

	#QuickSearch
	{
		top: {xen:calc '0 - {xen:property headerTabHeight2}'}px;
		z-index: 7500;
		{xen:property quickSearch}
	}

		#logoBlock #QuickSearchPlaceholder,
		#logoBlock #QuickSearch
		{
			top: 0;
			right: 0;
		}

		#QuickSearch:after,
		#QuickSearchPlaceholder:after
		{
			{xen:property quickSearchIcon}
		}

			#QuickSearch:after
			{
				pointer-events: none;

				color: {xen:property formElementPrompt.color};
				color: {xen:property quickSearchPlaceHolder.color};

				<xen:if is="{$searchBarOutsideWrapper}">
				color: {xen:property quickSearchPlaceHolderWrapped.color};
				</xen:if>
			}

			#QuickSearch.active:after,
			#QuickSearch.hasValue:after
			{
				display: none;
			}

			#QuickSearchPlaceholder:after
			{
				text-indent: 0;
				top: 1px;
				right: 0;
				left: 0;
				bottom: 0;
				text-align: center;
				color: {xen:property link.color};
				pointer-events: none;

				{xen:property searchBarPlaceholderColor}

				<xen:if is="{$searchBarOutsideWrapper}">
				{xen:property searchBarPlaceholderWrappedColor}
				</xen:if>
			}

		#QuickSearch .secondaryControls
		{
			display: none;
		}

		#QuickSearch.active
		{
			{xen:property quickSearchActive}
		}

	#QuickSearch .formPopup
	{
		background: transparent;
	}

	#QuickSearchQuery
	{
		{xen:property quickSearchInput}

		<xen:if is="{$searchBarOutsideWrapper}">
		{xen:property quickSearchInputWrapped}
		</xen:if>
	}

		#QuickSearchQuery:hover
		{
			{xen:property quickSearchInputHover}
		}

		#QuickSearch.active #QuickSearchQuery
		{
			{xen:property textCtrl}
			{xen:property activeQuickSearchInput}
		}

			#QuickSearch.active #QuickSearchQuery:hover
			{
				{xen:property textCtrlHover}
				{xen:property activeQuickSearchInputHover}
			}

			#QuickSearch.active #QuickSearchQuery:focus
			{
				{xen:property textCtrlFocus}
				{xen:property activeQuickSearchInputFocus}
			}

		#QuickSearchQuery:-moz-placeholder
		{
			<xen:set var="$placeholderStyle">
			{xen:property quickSearchPlaceHolder}

			<xen:if is="{$searchBarOutsideWrapper}">
			{xen:property quickSearchPlaceHolderWrapped}
			</xen:if>
			</xen:set>
			{xen:raw $placeholderStyle}
		}
		#QuickSearchQuery::-moz-placeholder
		{
			{xen:raw $placeholderStyle}
		}
		#QuickSearchQuery::-webkit-input-placeholder
		{
			{xen:raw $placeholderStyle}
		}
		#QuickSearchQuery:-ms-input-placeholder
		{
			{xen:raw $placeholderStyle}
		}
		#QuickSearchQuery::input-placeholder
		{
			{xen:raw $placeholderStyle}
		}

		#QuickSearchQuery:hover:-moz-placeholder
		{
			<xen:set var="$placeholderStyle">
			{xen:property quickSearchPlaceHolderHover}

			<xen:if is="{$searchBarOutsideWrapper}">
			{xen:property quickSearchPlaceHolderWrappedHover}
			</xen:if>
			</xen:set>
			{xen:raw $placeholderStyle}
		}
		#QuickSearchQuery:hover::-moz-placeholder
		{
			{xen:raw $placeholderStyle}
		}
		#QuickSearchQuery:hover::-webkit-input-placeholder
		{
			{xen:raw $placeholderStyle}
		}
		#QuickSearchQuery:hover:-ms-input-placeholder
		{
			{xen:raw $placeholderStyle}
		}
		#QuickSearchQuery:hover::input-placeholder
		{
			{xen:raw $placeholderStyle}
		}

		#QuickSearchQuery:focus:-moz-placeholder
		{
			{xen:property formElementPromptFocus}
		}
		#QuickSearchQuery:focus::-moz-placeholder
		{
			{xen:property formElementPromptFocus}
		}
		#QuickSearchQuery:focus::-webkit-input-placeholder
		{
			{xen:property formElementPromptFocus}
		}
		#QuickSearchQuery:focus:-ms-input-placeholder
		{
			{xen:property formElementPromptFocus}
		}
		#QuickSearchQuery:focus::input-placeholder
		{
			{xen:property formElementPromptFocus}
		}

		#QuickSearchQuery::-webkit-search-decoration,
		#QuickSearchQuery::-webkit-search-results-button,
		#QuickSearchQuery::-webkit-search-results-decoration
		{
			display: none;
		}

	#QuickSearch .formPopup .controlsWrapper
	{
		background: transparent;
		border-width: 0;
		box-shadow: none;
	}

	#QuickSearch .submitUnit .button
	{
		{xen:property quickSearchButton}
	}

	#QuickSearch input.button.primary
	{
		{xen:property quickSearchButtonPrimary}
	}

	#QuickSearch #commonSearches
	{
		float: right;
	}

	#QuickSearch .moreOptions
	{
		{xen:property quickSearchButtonMore}
	}

	#QuickSearch .submitUnit .button.PopupControl
	{
		{xen:property quickSearchButtonPopup}
	}

		#QuickSearch .submitUnit .button.PopupControl .arrowWidget
		{
			{xen:property quickSearchButtonPopupArrow}
		}

		#QuickSearch .submitUnit .button.PopupControl.PopupOpen
		{
			{xen:property quickSearchButtonPopupOpen}
		}

	/* Collapsed */
	<xen:if is="{xen:property enableAlternativeNavigation} || ({xen:property searchBarCollapse} && !{xen:property quickSearchInHeader})">
	#searchBar #QuickSearchPlaceholder,
	#searchBar #QuickSearch.show
	{
		display: block;
	}

	#searchBar #QuickSearchPlaceholder.hide,
	#searchBar #QuickSearch
	{
		display: none;
	}

		<xen:if is="{xen:property animatedSearchBar}">
		#searchBar .formPopup
		{
			width: auto;
		}

			#searchBar .active .formPopup
			{
				width: 250px;
			}

		#searchBar #QuickSearchQuery
		{
			width: 14px;
			opacity: 0;
		}

			#searchBar .active #QuickSearchQuery
			{
				width: 232px;
				opacity: 1;
			}

		#searchBar .primaryControls
		{
			text-align: right;
		}

		#searchBar .formPopup,
		#searchBar #QuickSearchQuery
		{
			transition: width .2s ease;
		}
		</xen:if>
	</xen:if>

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveWideWidth})
{
	<xen:if is="{xen:property enableAlternativeNavigation} || !{xen:property quickSearchInHeader}">
	.Responsive #QuickSearchPlaceholder
	{
		display: block;
	}

	.Responsive #QuickSearch
	{
		display: none;
	}
	</xen:if>

	.Responsive #QuickSearchPlaceholder.hide
	{
		display: none;
	}

	.Responsive #QuickSearch.show
	{
		display: block;
		margin-right: 5px;
	}

	<xen:if is="{xen:property animatedSearchBar}">
		.Responsive #searchBar .formPopup
		{
			width: auto;
		}

			.Responsive #searchBar .active .formPopup
			{
				width: 250px;
			}

		.Responsive #searchBar #QuickSearchQuery
		{
			width: 14px;
			opacity: 0;
		}

			.Responsive #searchBar .active #QuickSearchQuery
			{
				width: 232px;
				opacity: 1;
			}

		.Responsive #searchBar .primaryControls
		{
			text-align: right;
		}

		.Responsive #searchBar .formPopup,
		.Responsive #searchBar #QuickSearchQuery
		{
			transition: width .2s ease;
		}
		</xen:if>
}

<xen:if is="!{xen:property enableAlternativeNavigation} && {xen:property quickSearchInHeader}">
@media (max-width:{xen:property maxResponsiveMediumWidth})
{
	.Responsive #QuickSearch
	{
		display: none;
	}
}
</xen:if>

</xen:if>

