/* sidebar structural elements */
<xen:set var="$sidebarRight"><xen:if is="{xen:property sideBarLeftSide}">left<xen:else />right</xen:if></xen:set>
<xen:set var="$sidebarLeft"><xen:if is="{xen:property sideBarLeftSide}">right<xen:else />left</xen:if></xen:set>

.mainContainer
{
	 float: {$sidebarLeft};
	 margin-{$sidebarRight}: -{xen:calc '{xen:property sidebar.width} + 10'}px;
	 width: 100%;
}

	.mainContent
	{
		margin-{$sidebarRight}: {xen:calc '{xen:property sidebar.width} + 10'}px;
	}

		.mainContent.expanded > .expandItemWidth,
		.mainContent.expanded > .expandChildrenWidth > .expandWidth
		{
			margin-{$sidebarRight}: -{xen:calc '{xen:property sidebar.width} + 10'}px;
		}

.sidebar
{
	float: {$sidebarRight};
	{xen:property sidebar}
}

<xen:if is="{xen:property wrapSidebar}">
.hasSidebarContainer .mainContainer
{
	margin-{$sidebarRight}: -{xen:calc '{xen:property sidebar.width} + 10 + {xen:property sidebarWrapper.border-left-width} + {xen:property sidebarWrapper.border-right-width} + {xen:property sidebarWrapper.padding-left} + {xen:property sidebarWrapper.padding-right}'}px;
}

	.hasSidebarContainer .mainContent
	{
		margin-{$sidebarRight}: {xen:calc '{xen:property sidebar.width} + 10 + {xen:property sidebarWrapper.border-left-width} + {xen:property sidebarWrapper.border-right-width} + {xen:property sidebarWrapper.padding-left} + {xen:property sidebarWrapper.padding-right}'}px;
	}

	.sidebar.sidebarWrapped
	{
		{xen:property primaryContent}

		margin: 10px 0;
		<xen:if is="!{xen:property enableAlternativeNavigation} && {xen:property globalWrapper}">
		margin-top: 0;
		</xen:if>
		<xen:if is="!{xen:property globalWrapper}">
		margin-top: 0;
		</xen:if>

		{xen:property sidebarWrapper}
	}

	.sidebar.noWrapper
	{
		padding: 0;
	}

	.sidebar + .sidebar
	{
		margin-top: 0;
	}
</xen:if>

