.itemGallery {
	{xen:property sonnbXenGalleryGridItem};
	box-shadow: none;
	{xen:property primaryContent}
	max-width: {xen:property sonnb_xengallery_itemwidth}; 
	min-width: {xen:property sonnb_xengallery_itemwidth}; 
	margin-right: {xen:property sonnbXenGalleryGridItem.margin-bottom};
}
html.desktop .itemGallery:hover {
	{xen:property sonnbXenGalleryGridItemHover}
}
html.desktop .itemGallery:hover {
	{xen:property sonnbXenGalleryGridItemShadowHover}
}
.itemGallery.masonry-brick {
	margin-right: 0;
}
.galleryboxshadow .itemGallery {
	border: 0 none;
}
html.desktop .galleryboxshadow .itemGallery:hover {
	border: 0 none;
}
		.itemGallery .img { 
			{xen:property sonnbXenGalleryGridItemImage};
			background: transparent;
		}
		.itemGallery .img.loaded {
			background-image: none;
		}
		.itemGallery .img.broken {
			background-image: url("styles/sonnb/XenGallery/broken.png");
			background-color: {xen:property secondaryMedium};
			background-position: center center;
			background-repeat: no-repeat;
		}
		.itemGallery .img a{
			display: block; 
			overflow: hidden;
		}
		.itemGallery .img i.icon.gif{
			background-image: url("styles/sonnb/XenGallery/gif.png");
			background-size: 100% 100%;
			display: inline-block;
			height: 34px;
			width: 34px;
			left: 50%;
			top: 50%;
			margin-left: -17px;
			margin-top: -17px;
			position: absolute;
		}
		.itemGallery .img i.icon.video{
			background-image: url("styles/sonnb/XenGallery/video.png");
			background-size: 100% 100%;
			display: inline-block;
			height: 64px;
			width: 64px;
			left: 50%;
			top: 50%;
			margin-left: -32px;
			margin-top: -32px;
			position: absolute;
		}
		.itemGallery .img a img{
			margin: 0 auto;
			width: auto;
			max-width: {xen:property sonnb_xengallery_itemwidth};   
			position: relative;
		}
		.itemGallery .img a img.lazy {
			width: auto;
			display: none;
		}
		.hasJs .itemGallery .img a img.lazy {
			display: none;
		}

@media only screen and (max-width: 900px), only screen and (max-device-width: 900px)
{
