		width: 23%;
		min-width: inherit;
	}
	.itemGallery .img,
	.itemGallery .img a,
	.itemGallery .img a img {
		width: 100%;
		max-width: 100%;
	}
}

@media only screen and (max-width: 700px), only screen and (max-device-width: 700px)
{
	.itemGallery {
		width: 30%;
		min-width: inherit;
	}
	.itemGallery .img,
	.itemGallery .img a,
	.itemGallery .img a img {
		width: 100%;
		max-width: 100%;
	}
}

