	.relatedPhotos {
		{xen:property sonnbXG_view_relatedPhotoWrapper}
	}
		.relatedPhotos .scrollable {
			{xen:property sonnbXG_view_relatedPhotoContainer}
		}
			.relatedPhotos .scrollable .items {
				width:20000em; 
				position:absolute;
				top: 0;
			}
				.relatedPhotos .scrollable .items div {
					float:left;
				}
				.relatedPhotos .scrollable .items img{
					width:60px; 
					height:60px;
					opacity: 0.5;
				}
				.relatedPhotos .scrollable .items img:hover,
				.relatedPhotos .scrollable .items a.active img{
					/*outline: 2px solid #4b6789;*/
					opacity: 1;
				}
		.relatedPhotos .prev.left,
		.relatedPhotos .next.right{
			bottom: 0;
			height: 60px;
			top: 0;
			position: absolute;
			width: 20px;
			text-align: center;
		}

		.relatedPhotos .prev.left {

		}
		.relatedPhotos .next.right{
			right: 0;
		}					
		<xen:if is="!{$pageIsRtl}">
			.relatedPhotos .prev.left {
				left: 0;
			}
			.relatedPhotos .next.right {
				right: 0;
			}
		<xen:else />
			.relatedPhotos .prev.left {
				right: 0;
			}
			.relatedPhotos .next.right {
				left: 0;
			}
		</xen:if>
		.relatedPhotos .prev.left:hover, 
		.relatedPhotos .next.right:hover{
			cursor:pointer;
			background:linear-gradient(to bottom, #7487b8 0px, #405a9c 100%) repeat scroll 0 0 #405a9c;
		}
			.relatedPhotos .prev.left span, 
			.relatedPhotos .next.right span {
				display: block;
				height: 18px;
				left: 8px;
				position: absolute;
				top: 22px;
				width: 10px;
			}
			.relatedPhotos .prev.left span:before,
			.relatedPhotos .next.right span:before {
				color: {xen:property contentText};
			}
			.relatedPhotos .prev.left:hover span:before,
			.relatedPhotos .next.right:hover span:before {
				color: #FFF;
			}


