	html.phone .photoTag-tag,
	html.tablet .photoTag-tag {
		opacity: 0.8 !important;
	}
		.photoTag-tag .innerTag {
			{xen:property sonnbXG_view_taggingInner}
		}
		.photoTagForm {
			position: absolute;
			padding: 3px;
			line-height: normal;;
		}
			.photoTagForm .textCtrl {
				width: 98px;
			}
			.photoTagForm .button.primary {
				width: 50px;
			}
			.photoTagForm .button.primary[type="submit"] {
				margin-right: 3px;
			}
			.photoTag-tag .photoTag-delete {
				background: url("{xen:property imagePath}/xenforo/overlay/close.png") no-repeat scroll 0 0 transparent;
				cursor: pointer;
				display: inline;
				height: 36px;
				opacity: 1;
				position: absolute;
				right: -18px;
				top: -17px;
				width: 36px;
				z-index: 3200;
			}
		.photoTag-cpanel {
			-webkit-transition: opacity .3s;
			-moz-transition: opacity .3s;
			-ms-transition: opacity .3s;
			-o-transition: opacity .3s;
			transition: opacity .3s;

			-webkit-background-clip: padding-box;
			-moz-background-clip: padding-box;
			-ms-background-clip: padding-box;
			-o-background-clip: padding-box;

			-webkit-font-smoothing: antialiased;
			-moz-font-smoothing: antialiased;
			-ms-font-smoothing: antialiased;
			-o-font-smoothing: antialiased;

			filter: alpha(opacity=80);
			background-color: rgba(0, 0, 0, .8);
			bottom: 0;
			color: {xen:property faintTextColor};
			font-size: 13px;
			left: 0;
			padding: 0;
			position: absolute;
			width: 100%;
			display: none;
			padding: 8px 0;
		}
			.photoTag-cpanel a {
				font-weight: bold;
				color: {xen:property primaryMedium};
			}

