.prefix a { color: inherit; }

.prefix.prefixPrimary    { color: {xen:property primaryDark}; background-color: {xen:property primaryLighter}; border-color: {xen:property primaryLighter}; }
.prefix.prefixSecondary  { color: {xen:property secondaryDark}; background-color: {xen:property secondaryLighter}; border-color: {xen:property secondaryLighter}; }

.prefix.prefixRed        { color: white; background-color: red; border-color: #F88; }
.prefix.prefixGreen      { color: white; background-color: green; border-color: green; }
.prefix.prefixOlive      { color: black; background-color: olive; border-color: olive; }
.prefix.prefixLightGreen { color: black; background-color: lightgreen; border-color: lightgreen; }
.prefix.prefixBlue       { color: white; background-color: blue; border-color: #9d99ee; }
.prefix.prefixRoyalBlue  { color: white; background-color: royalblue; border-color: #9da7c5;  }
.prefix.prefixSkyBlue    { color: black; background-color: skyblue; border-color: skyblue; }
.prefix.prefixGray       { color: black; background-color: gray; border-color: #AAA; }
.prefix.prefixSilver     { color: black; background-color: silver; border-color: silver; }
.prefix.prefixYellow     { color: black; background-color: yellow; border-color: #E0E000; }
.prefix.prefixOrange     { color: black; background-color: orange; border-color: #FFC520; }

