/** Data tables **/

table.dataTable
{
	width: 100%;
	_width: 99.5%;
	margin: 10px 0;
	{xen:property primaryContent}
}

.dataTable caption
{
	{xen:property heading}
}

.dataTable tr.dataRow td
{
	border-bottom: 1px solid {xen:property innerTopBorder};
	padding: 5px 10px;
	word-wrap: break-word;
}

.dataTable tr.dataRow td.secondary
{
	background: {xen:property blocksInnerBackground};
}

.dataTable tr.dataRow th
{
	background: {xen:property primaryMedium};
	border-width: 0;
	color: {xen:property primaryLightest};
	font-size: 11px;
	padding: 5px 10px;
}

	.dataTable tr.dataRow th a
	{
		color: inherit;
		text-decoration: underline;
	}

.dataTable .dataRow .dataOptions
{
	text-align: right;
	white-space: nowrap;
	word-wrap: normal;
	padding: 0;
}

.dataTable .dataRow .important,
.dataTable .dataRow.important
{
	font-weight: bold;
}

.dataTable .dataRow .dataOptions a.secondaryContent
{
	display: inline-block;
	border-width: 0;
	border-radius: 0;
	border-left: 1px solid {xen:property innerTopBorder};
	box-shadow: none;
	filter: none;
	background-image: none;
	padding: 7px 10px 6px;
	font-size: 11px;
}

	.dataTable .dataRow .dataOptions a.secondaryContent:hover
	{
		background-color: {xen:property blocksInnerBackground};
		text-decoration: none;
	}

	.dataTable .dataRow .delete
	{
		padding: 0px;
		width: 26px;
		border-left: 1px solid {xen:property innerTopBorder};
	}	

		.dataTable .dataRow .delete a
		{
			display: block;
			background: transparent;
			cursor: pointer;

			padding: 5px;
			width: 16px;
			height: 16px;

			overflow: hidden;
			white-space: nowrap;
			text-indent: -1000px;

			position: relative;
		}

			.dataTable .dataRow .delete a:after
			{
				content: '\f00d';
				font-family: 'FontAwesome';
				font-size: 15px;
				display: inline-block;
				position: absolute;
				top: 5px;
				left: 0;
				right: 0;
				text-align: center;
				text-indent: 0;
				line-height: 15px;
				color: {xen:property secondaryMedium};
			}

