/* Overlay background */
#exposeMask
{
	<xen:if is="{xen:property overlayMaskImage}">
	background-image: url('{xen:property imagePath}/{xen:property overlayMaskImage}');
	</xen:if>
	background-color: {xen:property overlayMaskColorLogin} !important;
}

	#exposeMask.overlayExposeMask
	{
		background-color: {xen:property overlayMaskColor} !important;
	}

/* All overlays must have this */
.xenOverlay
{
	display: none;
	z-index: 10000;
	width: 90%;
	box-sizing: border-box;
	max-width: {xen:calc '{xen:property overlayFormWidth} + 90'}px; /*calc: 90=overlay padding+borders*/
}

	.xenOverlay .overlayScroll
	{
		max-height: 400px;
		overflow: auto;
	}

	.xenOverlay .overlayScroll.ltr
	{
		direction: ltr;
	}

	.xenOverlay .overlayScroll .sortable-placeholder
	{
		background-color: {xen:property primaryLighter};
	}

.overlayOnly /* needs a bit more specificity over regular buttons */
{
	display: none !important;
}

	.xenOverlay .overlayOnly
	{
		display: block !important;
	}

	.xenOverlay input.overlayOnly,
	.xenOverlay button.overlayOnly,
	.xenOverlay a.overlayOnly
	{
		display: inline !important;
	}

	.xenOverlay a.close 
	{
		{xen:property overlayCloseControl}
	}

		.xenOverlay a.close:hover
		{
			{xen:property overlayCloseControlHover}
		}

		.xenOverlay a.close:after
		{
			height: {xen:property overlayCloseControl.height};
			line-height: {xen:property overlayCloseControl.height};
			text-indent: 0;
			text-shadow: none;

			{xen:property overlayCloseGlyph}
		}

.xenOverlay .nonOverlayOnly
{
	display: none !important;
}

/* Generic form overlays */

.xenOverlay .formOverlay
{
	{xen:property formOverlay}
	margin: 0;
	border-color: {xen:helper rgba, {xen:property formOverlay.border-color}, {xen:property overlayBorderOpacity}};
}

	.Touch .xenOverlay .formOverlay
	{
		background: {xen:helper unrgba, {xen:property formOverlay.background-color}};
		box-shadow: none;
	}

	.xenOverlay .formOverlay a.muted,
	.xenOverlay .formOverlay .muted a
	{
		color: {xen:property mutedTextColor};
	}

	.xenOverlay .formOverlay .heading
	{
		{xen:property formOverlayHeading}

		<xen:if is="{$pageIsRtl}">
		{xen:property formOverlayHeadingRTL}
		</xen:if>
	}

	.xenOverlay .formOverlay .subHeading
	{
		{xen:property formOverlaySubHeading}
	}

	.xenOverlay .formOverlay .textHeading
	{
		{xen:property formOverlayTextHeading}
	color: inherit;
	}

	.xenOverlay .formOverlay > p
	{
		padding-left: {xen:property formOverlayHeading.padding-left};
		padding-right: {xen:property formOverlayHeading.padding-right};
	}

	.xenOverlay .formOverlay .textCtrl
	{
		{xen:property formOverlayTextCtrl}
	}

	.xenOverlay .formOverlay .textCtrl option
	{
		{xen:property formOverlayTextCtrl.background}
	}

	.xenOverlay .formOverlay .textCtrl:focus,
	.xenOverlay .formOverlay .textCtrl.Focus
	{
		{xen:property formOverlayTextCtrlFocus}
	}

	.xenOverlay .formOverlay .textCtrl:focus option
	{
		{xen:property formOverlayTextCtrlFocus.background}
	}

	.xenOverlay .formOverlay .textCtrl.disabled
	{
		{xen:property formOverlayTextCtrlDisabled}
	}

	.xenOverlay .formOverlay .textCtrl.disabled option
	{
		{xen:property formOverlayTextCtrlDisabled.background}
	}

	.xenOverlay .formOverlay .textCtrl.prompt
	{
		{xen:property formOverlayTextCtrlPrompt}
	}

	.xenOverlay .formOverlay .ctrlUnit > dt dfn,
	.xenOverlay .formOverlay .ctrlUnit > dd li .hint,
	.xenOverlay .formOverlay .ctrlUnit > dd .explain
	{
		{xen:property formOverlayLabelHint}
	}

	.xenOverlay .formOverlay a
	{
		{xen:property formOverlayLink}
	}

		.xenOverlay .formOverlay a.button
		{
			{xen:property formOverlayButton}
		}

	.xenOverlay .formOverlay .avatar img,
	.xenOverlay .formOverlay .avatar .img,
	.xenOverlay .formOverlay .avatarCropper
	{
		background-color: transparent;
	}

	/* tabs in form overlay */

	.xenOverlay .formOverlay .tabs /* the actual tabs */
	{
		{xen:property formOverlayTabs}
	}

		.xenOverlay .formOverlay .tabs a
		{
			{xen:property formOverlayTab}
		}

			.xenOverlay .formOverlay .tabs a:hover
			{
				{xen:property formOverlayTabHover}
			}

			.xenOverlay .formOverlay .tabs .active a
			{
				{xen:property formOverlayTabActive}
			}

	.xenOverlay .formOverlay .tabPanel /* panels switched with the tab controls */
	{
		{xen:property formOverlayTabPanel}
	}

	.xenOverlay .formOverlay .submitUnit
	{
		margin-bottom: 10px;
	}

/* Generic overlays */

.xenOverlay .section,
.xenOverlay .sectionMain
{
	{xen:property overlaySection}

	border-color: {xen:helper rgba, {xen:property overlaySection.border-color}, {xen:property overlayBorderOpacity}};
}

	.Touch .xenOverlay .section,
	.Touch .xenOverlay .sectionMain
	{
		border-color: {xen:helper unrgba, {xen:property overlaySection.border-color}};
		box-shadow: none;
	}

.xenOverlay > .section,
.xenOverlay > .sectionMain
{
	background: none;
	margin: 0;
}

	.xenOverlay .section .heading,
	.xenOverlay .sectionMain .heading
	{
		border-radius: 0;
		margin-bottom: 0;
	}

	.xenOverlay .section .subHeading,
	.xenOverlay .sectionMain .subHeading
	{
		margin-top: 0;
	}

	.xenOverlay .section .sectionFooter,
	.xenOverlay .sectionMain .sectionFooter
	{
		overflow: hidden; zoom: 1;
	}

		.xenOverlay .sectionFooter .buttonContainer
		{
			line-height: 31px;
		}

		.xenOverlay .sectionFooter .button,
		.xenOverlay .sectionFooter .buttonContainer
		{
			min-width: 75px;
			*min-width: 0;
			float: right;
			margin-left: 5px;
		}

			.xenOverlay .sectionFooter .buttonContainer .button
			{
				float: none;
				margin-left: 0;
			}

.xenOverlay .primaryContent, 
.xenOverlay .secondaryContent,
.xenOverlay .heading,
.xenOverlay .subHeading
{
	border-radius: 0;
	box-shadow: none;
}

/* The AJAX progress indicator overlay */

#AjaxProgress.xenOverlay
{
	width: 100%;
	max-width: none;
	overflow: hidden; zoom: 1;
}

	#AjaxProgress.xenOverlay .content
	{
		{xen:property ajaxProgress}
	}

		.Touch #AjaxProgress.xenOverlay .content
		{
			background-color: {xen:helper unrgba, {xen:property ajaxProgress.background-color}};
		}

/* Timed message for redirects */

.xenOverlay.timedMessage
{
	{xen:property redirectMessage}
}

	.xenOverlay.timedMessage .content
	{
		{xen:property redirectMessageContent}
	}

/* Growl-style message */

#StackAlerts
{
	position: fixed;
	bottom: 70px;
	left: 35px;
	z-index: 9999; /* in front of the expose mask */
}

	#StackAlerts .stackAlert
	{
		position: relative;
		{xen:property stackAlert}
	}

		#StackAlerts .stackAlertContent
		{
			{xen:property stackAlertContent}
			background: {xen:helper rgba, {xen:property stackAlertContent.background-color}, 0.9};
		}

		#StackAlerts .DismissParent .DismissCtrl
		{
			{xen:property stackAlertDismiss}
		}

/* Inline Editor */

.xenOverlay .section .messageContainer
{
	padding: 0;
}

.xenOverlay .section .messageContainer .mceLayout
{
	border: none;	
}

.xenOverlay .section .messageContainer tr.mceFirst td.mceFirst
{
	border-top: none;
}

.xenOverlay .section .messageContainer tr.mceLast td.mceLast,
.xenOverlay .section .messageContaner tr.mceLast td.mceIframeContainer
{
	border-bottom: none;
}

.xenOverlay .section .textCtrl.MessageEditor,
.xenOverlay .section .mceLayout,
.xenOverlay .section .bbCodeEditorContainer textarea
{
	width: 100% !important;
	min-height: 260px;
	_height: 260px;
	box-sizing: border-box;
}

/* Multi-quote */
.xenOverlay .MultiQuoteItem
{
	border-top: 1px solid {xen:property innerTopBorder};
	border-bottom: 1px solid {xen:property innerBottomBorder};
}

	.xenOverlay .MultiQuoteItem:first-child
	{
		border-top-width: 0;
	}

	.xenOverlay .MultiQuoteItem:last-child
	{
		border-bottom-width: 0;
	}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveMediumWidth})
{
	.Responsive .xenOverlay
	{
		width: 100%;
	}

	.Responsive .xenOverlay .formOverlay,
	.Responsive .xenOverlay .section,
	.Responsive .xenOverlay .sectionMain
	{
		border-radius: 10px;
		border-width: 10px;
	}

	.Responsive .xenOverlay a.close 
	{
		{xen:property overlayCloseResponsive}
	}
}
</xen:if>

/* ***************************** */
/* Popup Menus */

.Popup
{
	position: relative;
}

	.Popup.inline
	{
		display: inline;
	}

/** Popup menu trigger **/

.Popup .arrowWidget
{
	/* circle-arrow-down */
	{xen:property popupArrowClosed}
}

	.Popup .arrowWidget:after
	{
		{xen:property popupArrowGlyph}
		color: inherit;
	}

.PopupOpen .arrowWidget
{
	/* circle-arrow-up */
	{xen:property popupArrowOpen}
	opacity: 1;
}

.Popup .PopupControl,
.Popup.PopupContainerControl
{
	display: inline-block;
	cursor: pointer;
}

	.Popup .PopupControl:hover,
	.Popup.PopupContainerControl:hover
	{
		{xen:property popupControlClosedHover}
	}

	.Popup .PopupControl:focus,
	.Popup .PopupControl:active,
	.Popup.PopupContainerControl:focus,
	.Popup.PopupContainerControl:active
	{
		outline: 0;
	}

	.Popup .PopupControl.PopupOpen,
	.Popup.PopupContainerControl.PopupOpen
	{
		{xen:property popupControl}
	}

	.Popup .PopupControl.BottomControl.PopupOpen,
	.Popup.PopupContainerControl.BottomControl.PopupOpen
	{
		border-top-left-radius: {xen:property popupControl.border-bottom-left-radius};
		border-top-right-radius: {xen:property popupControl.border-bottom-right-radius};
		border-bottom-left-radius: {xen:property popupControl.border-top-left-radius};
		border-bottom-right-radius: {xen:property popupControl.border-top-left-radius};
	}

		.Popup .PopupControl.PopupOpen:hover,
		.Popup.PopupContainerControl.PopupOpen:hover
		{
			text-decoration: none;
		}

.subForumsPopup a.PopupControl
{
	margin: -3px 0;
	padding: 3px 5px;
}

/* Popup control on buttons */
.button.PopupControl,
.formPopup .button.PopupControl
{
	width: 23px;
	padding-left: 0;
	padding-right: 0;
}

	.button.PopupControl .arrowWidget
	{
		{xen:property buttonArrowWidget}
	}

		.button.PopupControl .arrowWidget:after
		{
			content: '\f0dd';
			font-family: 'FontAwesome';
		}


/* Popup control in navigation */
.navTabs .navTab.selected .tabLinks .arrowWidget,
.secondaryContent.blockLinksList.xengallery .Popup span.arrowWidget
{
	{xen:property navTabSelectedArrowWidget}
}

	.navTabs .navTab.selected .tabLinks .arrowWidget:after
	{
		{xen:property navTabSelectedArrowWidget.font}
	}

/** Menu body **/

.Menu
{
	/*background-color: {xen:property textCtrlBackground};*/

	{xen:property menu}

	min-width: {xen:property menuMinWidth};
	*width: {xen:property menuMinWidth};

	/* makes menus actually work... */
	position: absolute;
	z-index: 7500;
	display: none;
}

/* allow menus to operate when JS is disabled */
.Popup:hover .Menu
{
	display: block;
}

.Popup:hover .Menu.JsOnly
{
	display: none;
}

.Menu.BottomControl
{
	{xen:property menuBottomControl}
}

	.Menu > li > a,
	.Menu .menuRow
	{
		display: block;
	}

/* Menu header */

.Menu .menuHeader
{
	overflow: hidden; zoom: 1;
}

.Menu .menuHeader h3
{
	{xen:property menuHeaderTitle}
}

.Menu .menuHeader .muted
{
	{xen:property menuHeaderSubtitle}
}

/* Standard menu sections */

.Menu .primaryContent
{
	background-color: {xen:helper rgba, {xen:property primaryContent.background-color}, 0.96};

	{xen:property popupPrimaryContent}
}

.Menu .secondaryContent
{
	background-color: {xen:helper rgba, {xen:property secondaryContent.background-color}, 0.96};

	{xen:property popupSecondaryContent}
}

.Menu .sectionFooter
{
	background-color: {xen:helper rgba, {xen:property sectionFooter.background-color}, 0.9};

	{xen:property popupSectionFooter}
}

/* Links lists */

.Menu .blockLinksList
{	
	max-height: 400px;
	overflow: auto;
}

/* form popups */

.formPopup
{
	width: 250px;
	background-color: {xen:property contentBackground};
}

	.formPopup form,
	.formPopup .ctrlUnit
	{
		margin: 5px auto;
	}

		.formPopup .ctrlUnit
		{
		}

	.formPopup .textCtrl,
	.formPopup .button
	{
		width: 232px;
	}

	.formPopup .ctrlUnit > dt label
	{
		display: block;
		margin-bottom: 2px;
	}

	.formPopup .submitUnit dd
	{
		text-align: center;
	}

		.formPopup .ctrlUnit > dd .explain
		{
			margin: 2px 0 0;
		}

	.formPopup .primaryControls
	{
		zoom: 1;
		white-space: nowrap;
		word-wrap: normal;
		padding: 0 5px;
	}

		.formPopup .primaryControls input.textCtrl
		{
			margin-bottom: 0;
		}

	.formPopup .secondaryControls
	{
		padding: 0 5px;
	}

		.formPopup .controlsWrapper
		{
			{xen:property formPopupControlsWrapper}
		}

			.formPopup .controlsWrapper .textCtrl
			{
				width: 222px;
			}

	.formPopup .advSearchLink
	{
		display: block;
		text-align: center;
		padding: 5px;
		font-size: 11px;
		border-radius: 5px;
		border: 1px solid {xen:property primaryLighterStill};
		background: {xen:property primaryLightest};
	}

		.formPopup .advSearchLink:hover
		{
			background-color: {xen:property primaryLighterStill};
			text-decoration: none;
		}

.section
{
	{xen:property section}
}

.sectionMain
{
	{xen:property sectionMain}
}

	.sectionMain.mainContentBlock
	{
		{xen:property sectionMainContentBlock}
	}

.heading,
.xenForm .formHeader
{
	{xen:property heading}
}

	.heading a { color: {xen:property heading.color}; }

.subHeading
{
	{xen:property subHeading}

	<xen:if is="{$pageIsRtl}">
	{xen:property subHeadingRTL}
	</xen:if>
}

	.subHeading a { color: {xen:property subHeading.color}; }

	.sectionMain.mainContentBlock > .section:first-child > .subHeading:first-child
	{
		margin-top: -8px;
		border-radius: {xen:property primaryContent.border-radius};
	}

.textHeading,
.xenForm .sectionHeader
{
	{xen:property textHeading}
}

.xenForm .sectionHeader,
.xenForm .formHeader
{
	margin: 10px 0;
}

.primaryContent > .textHeading:first-child,
.secondaryContent > .textHeading:first-child
{
	margin-top: 0;
}

.larger.textHeading,
.xenForm .sectionHeader
{
	color: {xen:property primaryMedium};
	font-size: 11pt;
	margin-bottom: 6px;
}

	.larger.textHeading a,
	.xenForm .sectionHeader a
	{
		color: {xen:property primaryMedium};
	}

.primaryContent
{
	{xen:property primaryContent}
}

	.primaryContent a
	{
		{xen:property primaryContentLink}
	}

.secondaryContent
{
	{xen:property secondaryContent}
}

	.secondaryContent a
	{
		{xen:property secondaryContentLink}
	}

.sectionFooter
{
	overflow: hidden; zoom: 1;
	{xen:property sectionFooter}
}

	.sectionFooter a { color: {xen:property sectionFooter.color}; }

	.sectionFooter .left
	{
		float: left;
	}

	.sectionFooter .right
	{
		float: right;
	}

/* used for section footers with central buttons, esp. in report viewing */

.actionList
{
	text-align: center;
}

/* left-right aligned options */

.opposedOptions
{
	overflow: hidden; zoom: 1;
}

	.opposedOptions .left
	{
		float: left;
	}

	.opposedOptions .right
	{
		float: right;
	}

/* ***************************** */
/* Basic Tabs */

.tabs
{
	{xen:property tabsContainer}

	display: table;
	width: 100%;
	*width: auto;
	box-sizing: border-box;
}

.tabs li
{
	float: left;
}

.tabs li a,
.tabs.noLinks li
{
	{xen:property tab}
}

.tabs li:nth-child(2n) a,
.tabs.noLinks li:nth-child(2n)
{
	{xen:property tabEven}
}

.tabs li:hover a,
.tabs.noLinks li:hover
{
	{xen:property tabHover}		
}

.tabs li.active a,
.tabs.noLinks li.active
{
	{xen:property tabActive}
}

/* Tabs inside forms */

.xenForm .tabs,
.xenFormTabs
{
	padding: 5px {xen:property ctrlUnitEdgeSpacer} 0;
}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveNarrowWidth})
{
	.Responsive .tabs li
	{
		float: none;
	}

	.Responsive .tabs li a,
	.Responsive .tabs.noLinks li
	{
		{xen:property responsiveTab}
	}
}
</xen:if>

.albumThumbnailEditor
{
	overflow: hidden; zoom: 1;
	margin: 0 auto;
}

.albumThumbnailEditor .currentThumbnail
{
	float: left;
	display: block;
	width: 96px;
	text-align: center;
}

.albumThumbnailEditor .currentThumbnail img
{
	max-width: 96px;
}

.albumThumbnailEditor .modifyControls
{
	margin-left: 110px;
}

.albumThumbnailEditor .thumbnailUpload
{
	max-width: 100%;
	box-sizing: border-box;
	margin: 3px 0;
}

.albumThumbnailEditor .thumbnailAction
{
	overflow: hidden; zoom: 1;
	margin-bottom: 10px;
}

.albumThumbnailEditor .faint
{
	font-size: 11px;
}

.albumThumbnailEditor .submitUnit
{
	text-align: right;
}

.albumThumbnailEditor .albumThumbnail
{
	{xen:property avatar}
	background-color: transparent;
}

.short.pageNavLinkGroup
{
	margin: -5px 1% -5px 1%;
}

.gridSection
{
	{xen:property xengalleryResponsiveContainer}

	background: transparent;
}
{xen:helper clearfix, '.gridSection'}


.gridCol
{
	width: {xen:calc '(100 / {xen:property defaultPerRow}) - 2'}%;
	{xen:property xengalleryResponsiveColumn}
}

.gridCol:nth-child({xen:property defaultPerRow}n+1)
{
   clear: both;
}

.xengallery_watch_albums .gridSpan
{
	width: {xen:calc '(100 / ({xen:property defaultPerRow} + 1)) - 2'}%;
	{xen:property xengalleryResponsiveColumnNoSidebar}
}

.xengallery_watch_albums .CheckAll
{
	padding: 0;
	margin: 0;
	vertical-align: bottom;
	position: relative;
	top: -1px;
	overflow: hidden;
}

.albumContainer
{
	margin: 5px 0;
	position: relative;

	{xen:property primaryContent}
}

.albumContainer.deleted
{
	background-color: {xen:property primaryLighterStill};
	opacity: 0.3;
}

.albumContainer.InlineModChecked,
.albumContainer.deleted.InlineModChecked
{
{xen:property inlineModChecked}
}

.albumContainer .thumbImage
{
	width: 100%;
}

.albumContainer .titleSection
{
	padding: 3px;
	zoom: 1;
	overflow: hidden;
}

.albumContainer .dummyOverlay
{
	position: absolute;
	top: 50%;
	bottom: 50%;
	text-align: center;
	width: 100%;
}

.albumContainer .titleSection h3
{
	text-overflow: ellipsis;
	overflow: hidden;
	white-space: nowrap;
	font-weight: bold;
	font-size: 14px;
}

.albumContainer .titleSection h4
{
	font-size: 9px;
	font-style: italic;
	text-overflow: ellipsis;
	overflow: hidden;
	white-space: nowrap;
}

.albumContainer .statsSection
{
	padding: 4px;
	color: {xen:property primaryMedium};
	border-width: 0;
	border-radius: 0;
	background: none;
	box-shadow: none;
}

.albumContainer .statsSection .statCol
{
	display: block;
	float:left;
	margin: 1% 0 1% 0.8%;
}
.statCol:first-child { margin-left: 0; }

.albumContainer .statsSection .statSpan
{
	width: 24.2%;
}
{xen:helper clearfix, '.statsSection'}

.albumContainer .statsSection div
{
	width: 48%;
	display: inline-block;
	padding-bottom: 3px;
	overflow: hidden;
	white-space: nowrap;
	text-overflow: ellipsis;
}

.albumContainer .statsSection i
{
	font-size: 16px;
	width: 20px;
	display: inline-block;
	text-align: center;
	color: {xen:property primaryMedium};
}

.albumContainer .albumControls
{
	padding: 1px 5px 5px 5px;
	text-align: right;
	border-bottom: 0;
	border-width: 0;
	border-radius: 0;
	border-top: 1px solid {xen:property innerBottomBorder};
	background: none;
	box-shadow: none;
	position: relative;
}

	.albumContainer .albumControls:after
	{
		content: '';
		position: absolute;
		top: 0;
		left: 0;
		right: 0;
		border-top: 1px solid {xen:property innerTopBorder};
	}

.albumContainer .albumControls .albumLabels
{
	display: inline-block;
	text-align: right;
}

.albumLabels .albumLabel
{
	padding: 1px 5px;
	text-align: center;
	display: inline-block;
	margin-top: 5px;
	min-width: 12px;

	background-image: none;
	box-shadow: none;
