<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveWideWidth})
{
	.Responsive .detailContainer .statsSection i
	{
		font-size: 105%;
	}

	.gridCol:nth-child({xen:property defaultPerRow}n+1),
	.xengallery_find_new_media .gridSpan:nth-child({xen:calc '{xen:property defaultPerRow} + 1'}n+1)
	{
		clear: none;
	}

	.Responsive .gridSpan,
	.Responsive .gridCol
	{
		width: {xen:calc '(100 / {xen:property wideWidthPerRow}) - 2'}%;
	}

	.Responsive .gridSpan:nth-child({xen:property wideWidthPerRow}n+1),
	.Responsive .gridCol:nth-child({xen:property wideWidthPerRow}n+1)
	{
		clear: both;
	}

	.Responsive .thumbnailOverlay .overlayDetails .infoContainer .secondRow .categoryInfo
	{
		display: block;
		width: 100%;
	}

	.Responsive .thumbnailOverlay .overlayDetails .infoContainer .secondRow .ratingInfo
	{
		display: block;
		width: 100%;
	}
}

@media (max-width:{xen:property maxResponsiveMediumWidth})
{
	.Responsive .gridSpan:nth-child({xen:property wideWidthPerRow}n+1),
	.Responsive .gridCol:nth-child({xen:property wideWidthPerRow}n+1)
	{
		clear: none;
	}

	.Responsive .gridSpan,
	.Responsive .gridCol
	{
		width: {xen:calc '(100 / {xen:property mediumWidthPerRow}) - 2'}%;
	}

	.Responsive .gridSpan:nth-child({xen:property mediumWidthPerRow}n+1),
	.Responsive .gridCol:nth-child({xen:property mediumWidthPerRow}n+1)
	{
		clear: both;
	}

	.Responsive .detailContainer .statsSection i
	{
		font-size: 100%;
	}
}

@media (max-width:{xen:property maxResponsiveNarrowWidth})
{
	.Responsive .detailContainer .statsSection div
	{
		display: inline-block;
		width: 45%;
	}

	.Responsive .albumLabels .albumLabel
	{
		font-size: 9px;
	}

	.Responsive #InlineModOverlay
	{
		margin-left: 30px;
	}

	.Responsive .InlineMod.SelectionCountContainer
	{
		float: left;
	}
}

@media (max-width:340px)
{
	.Responsive .gridGroup
	{
		margin-left: 10%;
		margin-right: 10%;
	}

	.Responsive .gridSpan:nth-child({xen:property mediumWidthPerRow}n+1),
	.Responsive .gridCol:nth-child({xen:property mediumWidthPerRow}n+1)
	{
		clear: both;
	}

	.Responsive .gridSpan,
	.Responsive .gridCol
	{
		width: {xen:calc '(100 / {xen:property narrowWidthPerRow}) - 2'}%;
	}

	.Responsive .gridSpan:nth-child({xen:property narrowWidthPerRow}n+1),
	.Responsive .gridCol:nth-child({xen:property narrowWidthPerRow}n+1)
	{
		clear: both;
	}
}
</xen:if>

